// Frozen R backend source snapshot, bundled solely for user-requested local replay.
// Generated from the same R functions as the reference API. CI rejects drift.
export const REFERENCE_R_SOURCE_FILES = {"server.R":"# PMx Explain multi-omics reference R backend\n# Run with: Rscript multiomics-engine/run_backend.R\n# Default endpoint: http://127.0.0.1:8787\n\nor_else <- function(x, y) {\n  if (is.null(x) || !length(x) || (length(x) == 1L && is.na(x))) y else x\n}\n\n# plumber::plumb() evaluates server.R from its own directory, whereas\n# Rscript-based tests source it from the repository root. Resolve dependency\n# paths explicitly in both supported working directories; otherwise the\n# live /health and /run API cannot even start.\nreference_backend_dir <- if(file.exists(file.path(\"multiomics-engine\",\"advanced_methods.R\"))) {\n  \"multiomics-engine\"\n} else if(file.exists(\"advanced_methods.R\")) {\n  \".\"\n} else {\n  stop(\"Cannot locate local multiomics-engine R dependencies. Start the backend from the repository root.\",call.=FALSE)\n}\nsource(file.path(reference_backend_dir, \"advanced_methods.R\"), local = TRUE)\nsource(file.path(reference_backend_dir, \"paired_rnaseq_reference.R\"), local = TRUE)\nsource(file.path(reference_backend_dir, \"reference_full_results.R\"), local = TRUE)\nsource(file.path(reference_backend_dir, \"external_validation.R\"), local = TRUE)\n\nnormalise_text <- function(x) trimws(as.character(or_else(x, \"\")))\n\ncanonical_omic <- function(x) {\n  key <- tolower(gsub(\"[^a-z0-9]+\", \"_\", normalise_text(x)))\n  if (key %in% c(\"transcriptomics\",\"transcriptome\",\"transcriptomique\",\"rna\",\"rnaseq\",\"rna_seq\",\"gene_expression\",\"mrna\",\"arn\")) return(\"transcriptomics\")\n  if (key %in% c(\"proteomics\",\"proteome\",\"proteomique\",\"protein\",\"proteins\",\"proteine\",\"proteines\",\"lfq\")) return(\"proteomics\")\n  if (key %in% c(\"metabolomics\",\"metabolome\",\"metabolomique\",\"metabolite\",\"metabolites\",\"met\")) return(\"metabolomics\")\n  \"\"\n}\n\nread_csv_text <- function(text) {\n  utils::read.csv(\n    text = text,\n    check.names = FALSE,\n    stringsAsFactors = FALSE,\n    na.strings = c(\"\", \"NA\", \"NaN\", \"null\")\n  )\n}\n\nmapping_value <- function(mapping, key) {\n  value <- mapping[[key]]\n  if (is.null(value) || !nzchar(as.character(value))) return(NULL)\n  as.character(value)\n}\n\ncanonical_metadata <- function(raw, mapping, covariates = character()) {\n  out <- data.frame(row.names = seq_len(nrow(raw)))\n  fields <- c(\n    subject_id=\"subject_id\", sample_id=\"sample_id\", assay_id=\"assay_id\", omic=\"omic\",\n    condition=\"condition\", timepoint=\"timepoint\", batch=\"batch\",\n    technical_replicate=\"technical_replicate\", outcome=\"outcome\",\n    survival_time=\"survival_time\", survival_event=\"survival_event\",\n    sample_type=\"sample_type\", injection_order=\"injection_order\"\n  )\n  for (target in names(fields)) {\n    source_col <- mapping_value(mapping, fields[[target]])\n    out[[target]] <- if (!is.null(source_col) && source_col %in% names(raw)) raw[[source_col]] else rep(\"\", nrow(raw))\n  }\n  out$omic <- vapply(out$omic, canonical_omic, character(1))\n  for (col in covariates) if (col %in% names(raw)) out[[col]] <- raw[[col]]\n  out\n}\n\nmatrix_samples_by_features <- function(text, expected_assays, strict_exact=FALSE) {\n  df <- read_csv_text(text)\n  if (ncol(df) < 2L) stop(\"Matrix needs an identifier column and at least one value column.\")\n  first <- names(df)[1]\n  column_hits <- sum(names(df)[-1] %in% expected_assays)\n  row_hits <- sum(as.character(df[[first]]) %in% expected_assays)\n\n  if (row_hits > column_hits) {\n    if(isTRUE(strict_exact)){\n      csv_ids<-as.character(df[[first]])\n      if(anyNA(csv_ids)||anyDuplicated(csv_ids)||\n         length(csv_ids)!=length(expected_assays)||\n         !setequal(csv_ids,expected_assays))\n        stop(\"R1 RNA-seq CSV row-wise assay IDs differ from the exact metadata manifest: no unlisted or missing assays\")\n    }\n    keep <- as.character(df[[first]]) %in% expected_assays\n    x <- as.matrix(df[keep, -1, drop=FALSE])\n    storage.mode(x) <- \"double\"\n    rownames(x) <- as.character(df[[first]][keep])\n    return(x)\n  }\n\n  feature_ids <- as.character(df[[first]])\n  if(isTRUE(strict_exact)) {\n    csv_ids<-names(df)[-1L]\n    if(length(csv_ids)!=length(expected_assays)||\n       anyDuplicated(csv_ids)||!setequal(csv_ids,expected_assays))\n      stop(\"R1 RNA-seq CSV column-wise assay IDs differ from the exact metadata manifest: no unlisted or missing assays\")\n    if(anyNA(feature_ids)||anyDuplicated(feature_ids)||\n       any(!nzchar(feature_ids)))\n      stop(\"R1 RNA-seq CSV contains missing or duplicate feature identifiers\")\n  }\n  x <- as.matrix(df[, -1, drop=FALSE])\n  storage.mode(x) <- \"double\"\n  rownames(x) <- feature_ids\n  x <- t(x)\n  x[rownames(x) %in% expected_assays, , drop=FALSE]\n}\n\n# Upstream assay-level R1 integrity check BEFORE technical aggregation.\n# run_deseq2_counts() otherwise only sees the aggregate and cannot detect\n# assays silently dropped by the browser CSV orientation/identifier join.\n# No implicit dropping of blanks, QC injections or unknown assay types in\n# R1 confirmatory RNA-seq. The explicitly scoped cohort must consist of\n# measured biological samples only; exclusions belong in the preregistered\n# study manifest, not silently inside the bridge.\nrnaseq_confirmatory_sample_type_check <- function(layer_meta) {\n  if(!is.data.frame(layer_meta)||!nrow(layer_meta)||\n     !\"sample_type\"%in%names(layer_meta))\n    stop(\"R1 requires an explicit nonempty biological sample-type manifest\")\n  typ<-tolower(gsub(\"[^a-z0-9]+\",\"_\",\n    trimws(as.character(layer_meta$sample_type))))\n  if(anyNA(typ)||any(!typ%in%c(\"biological\",\"biological_sample\",\"sample\")))\n    stop(\"R1 cannot automatically exclude QC/blanks or infer unknown sample types; supply a manifest of biological samples only\")\n  invisible(TRUE)\n}\n\n# The researcher must explicitly prespecify the direction and identities\n# of the primary condition contrast. Alphabetical sort is NOT a substitute.\nrnaseq_confirmatory_explicit_contrast <- function(protocol,group_names) {\n  requested<-unlist(protocol$rnaPrimaryContrast,use.names=FALSE)\n  group_names<-as.character(group_names)\n  if(length(group_names)!=2L||anyNA(group_names)||\n     any(!nzchar(group_names))||anyDuplicated(group_names)||\n     !is.character(requested)||length(requested)!=3L||\n     anyNA(requested)||any(!nzchar(requested))||\n     !identical(requested[[1L]],\"condition\")||\n     identical(requested[[2L]],requested[[3L]])||\n     !setequal(requested[2:3],group_names))\n    stop(\"R1 confirmatory RNA-seq requires an explicit valid [condition, comparison, reference] contrast; alphabetical guessing is prohibited\")\n  requested\n}\n\nrnaseq_confirmatory_assay_integrity <- function(x, layer_meta) {\n  rnaseq_confirmatory_sample_type_check(layer_meta)\n  if(!is.matrix(x)||is.null(rownames(x))||\n     anyNA(rownames(x))||anyDuplicated(rownames(x))||\n     any(!nzchar(rownames(x)))||!is.data.frame(layer_meta)||\n     !all(c(\"assay_id\",\"sample_id\",\"subject_id\",\"condition\")%in%names(layer_meta)))\n    stop(\"R1 raw-count assay manifest requires unique measured assay identifiers\")\n  for(field in c(\"assay_id\",\"sample_id\",\"subject_id\",\"condition\")){\n    v<-as.character(layer_meta[[field]])\n    if(anyNA(v)||any(!nzchar(trimws(v))))\n      stop(paste(\"R1 assay manifest has missing or blank field:\",field))\n  }\n  if(anyDuplicated(as.character(layer_meta$assay_id))||\n     nrow(x)!=nrow(layer_meta)||\n     !setequal(rownames(x),as.character(layer_meta$assay_id)))\n    stop(\"R1 assay manifest and measured raw-count matrix have nonidentical assay IDs; no silent sample loss\")\n  if(!is.numeric(x)||is.null(colnames(x))||\n     anyNA(colnames(x))||anyDuplicated(colnames(x))||\n     any(!nzchar(colnames(x)))||any(!is.finite(x))||any(x<0)||\n     any(abs(x-round(x))>1e-8)||any(rowSums(x)<=0))\n    stop(\"R1 raw-count assay matrix contains invalid/missing/fractional measurements or empty assay libraries: never sum with na.rm=TRUE\")\n  for(sample in unique(as.character(layer_meta$sample_id))){\n    m<-layer_meta[as.character(layer_meta$sample_id)==sample,,drop=FALSE]\n    for(field in c(\"subject_id\",\"condition\",\"batch\")){\n      if(!field%in%names(m))next\n      v<-unique(as.character(m[[field]]))\n      if(length(v)>1L)\n        stop(paste(\"R1 technical replicates have inconsistent\",field,\n                   \"for one biological sample\"))\n    }\n  }\n  list(status=\"assay_identifiers_exact\",measured_assays=nrow(x),\n       biological_samples=length(unique(layer_meta$sample_id)),\n       assay_loss_detected=FALSE,certified=FALSE)\n}\n\naggregate_technical_replicates <- function(x, layer_meta, value_type) {\n  layer_meta <- layer_meta[match(rownames(x), layer_meta$assay_id), , drop=FALSE]\n  valid <- !is.na(layer_meta$sample_id) & nzchar(layer_meta$sample_id)\n  x <- x[valid, , drop=FALSE]\n  layer_meta <- layer_meta[valid, , drop=FALSE]\n  sample_ids <- unique(layer_meta$sample_id)\n\n  aggregate_one <- function(id) {\n    rows <- which(layer_meta$sample_id == id)\n    if (length(rows) == 1L) return(as.numeric(x[rows, ]))\n    if (value_type %in% c(\"raw_counts\",\"spectral_count\")) {\n      colSums(x[rows, , drop=FALSE], na.rm=TRUE)\n    } else {\n      colMeans(x[rows, , drop=FALSE], na.rm=TRUE)\n    }\n  }\n\n  agg <- t(vapply(sample_ids, aggregate_one, numeric(ncol(x))))\n  colnames(agg) <- colnames(x)\n  rownames(agg) <- sample_ids\n\n  meta <- do.call(rbind, lapply(sample_ids, function(id) {\n    row <- layer_meta[which(layer_meta$sample_id == id)[1], , drop=FALSE]\n    row$assay_id <- id\n    row\n  }))\n  rownames(meta) <- meta$sample_id\n  list(matrix=agg, metadata=meta)\n}\n\ncanonical_sample_type <- function(x) {\n  key <- tolower(gsub(\"[^a-z0-9]+\", \"_\", normalise_text(x)))\n  if (key %in% c(\"blank\",\"solvent_blank\",\"process_blank\",\"extraction_blank\",\"method_blank\")) return(\"blank\")\n  if (key %in% c(\"qc\",\"pooled_qc\",\"quality_control\",\"quality_control_pool\",\"pooled\",\"pool_qc\")) return(\"qc\")\n  \"biological\"\n}\n\nreference_preprocess_matrix <- function(x, layer, value_type) {\n  x <- as.matrix(x)\n  storage.mode(x) <- \"double\"\n  finite <- x[is.finite(x)]\n  has_negative <- length(finite) && any(finite < 0)\n  positive <- finite[finite > 0]\n  pseudo <- if (length(positive)) max(min(positive) / 2, 1e-12) else 1e-12\n  is_counts <- identical(layer, \"transcriptomics\") && identical(value_type, \"raw_counts\")\n  is_spectral <- identical(layer, \"proteomics\") && identical(value_type, \"spectral_count\")\n  explicitly_log <- value_type %in% c(\"log_expression\",\"log_intensity\",\"log_abundance\")\n  as_supplied <- value_type %in% c(\"normalized\",\"unknown\") || (has_negative && !is_counts && !is_spectral && !explicitly_log)\n  log_positive <- value_type %in% c(\"tpm\",\"lfq_intensity\",\"peak_area\",\"concentration\")\n  median_center <- (layer == \"proteomics\" && value_type == \"lfq_intensity\") ||\n    (layer == \"metabolomics\" && value_type == \"peak_area\")\n  steps <- character()\n\n  out <- x\n  if (is_counts || is_spectral) {\n    totals <- rowSums(ifelse(is.finite(x) & x > 0, x, 0), na.rm=TRUE)\n    totals[!is.finite(totals) | totals <= 0] <- 1\n    out <- sweep(x, 1, totals, \"/\") * 1e6\n    out <- log2(out + 0.5)\n    steps <- c(steps, if (is_counts) \"CPM + log2(CPM + 0.5)\" else \"library-size normalisation + log2\")\n  } else if (explicitly_log || as_supplied) {\n    steps <- c(steps, if (explicitly_log) \"already log-transformed\" else \"kept as supplied\")\n  } else if (log_positive) {\n    out <- log2(pmax(x, 0) + pseudo)\n    out[!is.finite(x)] <- NA_real_\n    steps <- c(steps, sprintf(\"log2(value + %.4g)\", pseudo))\n  }\n\n  if (median_center) {\n    med <- apply(out, 1, stats::median, na.rm=TRUE)\n    med[!is.finite(med)] <- NA_real_\n    target <- stats::median(med, na.rm=TRUE)\n    for (i in seq_len(nrow(out))) {\n      if (is.finite(med[i]) && is.finite(target)) out[i,] <- out[i,] - med[i] + target\n    }\n    steps <- c(steps, \"sample-wise median centering\")\n  }\n\n  list(matrix=out, steps=steps)\n}\n\napply_ms_qc_reference <- function(x, meta, protocol) {\n  x <- as.matrix(x)\n  storage.mode(x) <- \"double\"\n  meta <- meta[match(rownames(x), meta$assay_id), , drop=FALSE]\n  sample_types <- vapply(meta$sample_type, canonical_sample_type, character(1))\n  orders <- suppressWarnings(as.numeric(meta$injection_order))\n  blank_idx <- which(sample_types == \"blank\")\n  qc_idx <- which(sample_types == \"qc\")\n  bio_idx <- which(sample_types == \"biological\")\n  if (!length(bio_idx)) stop(\"Metabolomics reference QC found no biological injections.\")\n\n  blank_mode_raw <- tolower(as.character(or_else(protocol$msBlankFilter, \"flag\")))\n  blank_mode <- if (blank_mode_raw %in% c(\"off\",\"no\",\"false\")) {\n    \"off\"\n  } else if (blank_mode_raw %in% c(\"remove\",\"yes\",\"true\")) {\n    \"remove\"\n  } else {\n    \"flag\"\n  }\n  blank_filter <- blank_mode != \"off\"\n  blank_fold <- suppressWarnings(as.numeric(or_else(protocol$msBlankFold, 5)))\n  if (!is.finite(blank_fold) || blank_fold < 1) blank_fold <- 5\n\n  rsd_filter <- !identical(or_else(protocol$msQcRsdFilter, \"yes\"), \"no\") &&\n    !identical(or_else(protocol$msQcRsdFilter, TRUE), FALSE)\n  rsd_threshold <- suppressWarnings(as.numeric(or_else(protocol$msQcRsdThreshold, 0.30)))\n  if (!is.finite(rsd_threshold) || rsd_threshold <= 0) rsd_threshold <- 0.30\n\n  drift_requested <- !identical(or_else(protocol$msDriftCorrection, \"yes\"), \"no\") &&\n    !identical(or_else(protocol$msDriftCorrection, TRUE), FALSE)\n  mnar_strategy <- as.character(or_else(protocol$msMnarStrategy, \"none\"))\n\n  blank_filtered <- character()\n  if (blank_filter && length(blank_idx) >= 2L) {\n    blank_med <- apply(x[blank_idx,,drop=FALSE], 2, stats::median, na.rm=TRUE)\n    bio_med <- apply(x[bio_idx,,drop=FALSE], 2, stats::median, na.rm=TRUE)\n    contaminated <- is.finite(blank_med) & blank_med > 0 & is.finite(bio_med) & bio_med < blank_fold * blank_med\n    blank_filtered <- colnames(x)[contaminated]\n    if (identical(blank_mode, \"remove\")) x <- x[,!contaminated,drop=FALSE]\n  }\n\n  drift_corrected <- 0L\n  ordered_qc <- qc_idx[is.finite(orders[qc_idx])]\n  # Five QC injections suffice for a *linear* drift check, not a\n  # nonlinear LOESS curve. Nonlinear fitting needs >= 8 QC injections\n  # spanning the sequence (clinical untargeted MS QC guidelines).\n  if (drift_requested && length(ordered_qc) >= 5L && length(unique(orders[ordered_qc])) >= 5L) {\n    ordered_all <- which(is.finite(orders))\n    for (j in seq_len(ncol(x))) {\n      values <- x[,j]\n      positive <- values[is.finite(values) & values > 0]\n      if (length(positive) < 5L) next\n      pseudo <- max(min(positive) / 2, 1e-12)\n      use_qc <- ordered_qc[is.finite(values[ordered_qc]) & values[ordered_qc] >= 0]\n      if (length(use_qc) < 5L || length(unique(orders[use_qc])) < 5L) next\n\n      qdat <- data.frame(order=orders[use_qc], response=log(values[use_qc] + pseudo))\n      pred_all <- pred_qc <- NULL\n      # Never extrapolate correction beyond pooled-QC support; require QC\n      # injections to bracket every biological injection being adjusted.\n      in_support <- orders[ordered_all] >= min(qdat$order) &\n        orders[ordered_all] <= max(qdat$order)\n      if (nrow(qdat) >= 8L && length(unique(qdat$order)) >= 8L) {\n        adaptive_span <- min(1, max(0.6, 5 / nrow(qdat)))\n        fit <- try(stats::loess(\n          response ~ order, data=qdat, span=adaptive_span, degree=1,\n          family=\"symmetric\", control=stats::loess.control(surface=\"direct\")\n        ), silent=TRUE)\n        if (!inherits(fit,\"try-error\")) {\n          pred_all <- suppressWarnings(try(stats::predict(fit, newdata=data.frame(order=orders[ordered_all])), silent=TRUE))\n          pred_qc <- suppressWarnings(try(stats::predict(fit, newdata=data.frame(order=orders[use_qc])), silent=TRUE))\n        }\n      }\n      loess_ok <- !inherits(pred_all,\"try-error\") && !inherits(pred_qc,\"try-error\") &&\n        sum(is.finite(pred_all)) >= max(3L, ceiling(length(ordered_all) * 0.5)) &&\n        sum(is.finite(pred_qc)) >= 3L\n      if (!loess_ok) {\n        fit_lm <- try(stats::lm(response ~ order, data=qdat), silent=TRUE)\n        if (inherits(fit_lm,\"try-error\")) next\n        pred_all <- try(stats::predict(fit_lm, newdata=data.frame(order=orders[ordered_all])), silent=TRUE)\n        pred_qc <- try(stats::predict(fit_lm, newdata=data.frame(order=orders[use_qc])), silent=TRUE)\n        if (inherits(pred_all,\"try-error\") || inherits(pred_qc,\"try-error\")) next\n      }\n      reference <- stats::median(pred_qc[is.finite(pred_qc)], na.rm=TRUE)\n      if (!is.finite(reference)) next\n      valid <- in_support & is.finite(pred_all) & is.finite(values[ordered_all]) & values[ordered_all] >= 0\n      if (!any(valid)) next\n      ids <- ordered_all[valid]\n      corrected <- exp(log(values[ids] + pseudo) - pred_all[valid] + reference) - pseudo\n      x[ids,j] <- pmax(0, corrected)\n      drift_corrected <- drift_corrected + 1L\n    }\n  }\n\n  rsd_filtered <- character()\n  if (rsd_filter && length(qc_idx) >= 3L && ncol(x)) {\n    rsd <- vapply(seq_len(ncol(x)), function(j) {\n      values <- x[qc_idx,j]\n      values <- values[is.finite(values) & values >= 0]\n      if (length(values) < 3L) return(NA_real_)\n      m <- mean(values)\n      if (!is.finite(m) || m <= 0) return(NA_real_)\n      stats::sd(values) / m\n    }, numeric(1))\n    unstable <- is.finite(rsd) & rsd > rsd_threshold\n    rsd_filtered <- colnames(x)[unstable]\n    x <- x[,!unstable,drop=FALSE]\n  }\n\n  imputed <- 0L\n  affected_features <- 0L\n  if (identical(mnar_strategy, \"left_censored\") && ncol(x)) {\n    for (j in seq_len(ncol(x))) {\n      observed <- x[bio_idx,j]\n      observed <- observed[is.finite(observed) & observed > 0]\n      if (length(observed) < 3L) next\n      logs <- log(observed)\n      spread <- stats::mad(logs, center=stats::median(logs), constant=1.4826, na.rm=TRUE)\n      if (!is.finite(spread) || spread <= 0) spread <- stats::sd(logs, na.rm=TRUE)\n      if (!is.finite(spread) || spread <= 0) spread <- 1\n      min_positive <- min(observed)\n      q10 <- as.numeric(stats::quantile(logs, 0.10, na.rm=TRUE, names=FALSE, type=7))\n      low <- max(min_positive * 0.01, min(min_positive * 0.8, exp(min(log(min_positive)-0.2*spread, q10-1.28*spread))))\n      missing <- bio_idx[!is.finite(x[bio_idx,j])]\n      if (length(missing)) {\n        x[missing,j] <- low\n        imputed <- imputed + length(missing)\n        affected_features <- affected_features + 1L\n      }\n    }\n  }\n\n  warnings <- character()\n  if (blank_filter && length(blank_idx) < 2L) warnings <- c(warnings, \"Blank assessment requested but fewer than two blank injections were annotated.\")\n  if (identical(blank_mode, \"remove\") && length(blank_idx) >= 2L) warnings <- c(warnings, \"Blank-associated features were excluded using the declared ratio; retain a flag-only sensitivity analysis for confirmatory work.\")\n  if (drift_requested && length(ordered_qc) < 5L) warnings <- c(warnings, \"Drift correction requested but fewer than five ordered pooled-QC injections were available.\")\n  if (drift_requested && length(ordered_qc) >= 5L && length(ordered_qc) < 8L) warnings <- c(warnings, \"Fewer than eight ordered pooled-QCs: no nonlinear LOESS was fitted; only a linear drift model was allowed. Confirm with a no-drift-correction sensitivity analysis.\")\n  if (drift_requested && length(ordered_qc) >= 5L && any(is.finite(orders[bio_idx]) & (orders[bio_idx] < min(orders[ordered_qc]) | orders[bio_idx] > max(orders[ordered_qc])))) warnings <- c(warnings, \"Some biological injections fall outside the QC bracketing range and were not drift-corrected (no extrapolation).\")\n  if (rsd_filter && length(qc_idx) < 3L) warnings <- c(warnings, \"QC RSD filter requested but fewer than three pooled-QC injections were annotated.\")\n  if (identical(mnar_strategy, \"left_censored\")) warnings <- c(warnings, \"Left-censored imputation is a declared sensitivity assumption; retain a no-imputation analysis for confirmatory work.\")\n\n  list(\n    matrix=x[bio_idx,,drop=FALSE],\n    metadata=meta[bio_idx,,drop=FALSE],\n    summary=list(\n      method=\"R MS QC: blank filter + LOESS only when >=8 ordered QC (linear fallback >=5) within QC order support + pooled-QC RSD\",\n      biological_injections=length(bio_idx),\n      blank_injections=length(blank_idx),\n      qc_injections=length(qc_idx),\n      blank_mode=blank_mode,\n      blank_fold=blank_fold,\n      blank_flagged_features=length(blank_filtered),\n      blank_removed_features=if (identical(blank_mode, \"remove\")) length(blank_filtered) else 0L,\n      blank_filtered_features=if (identical(blank_mode, \"remove\")) length(blank_filtered) else 0L,\n      drift_requested=drift_requested,\n      drift_corrected_features=drift_corrected,\n      qc_rsd_threshold=rsd_threshold,\n      qc_rsd_filtered_features=length(rsd_filtered),\n      mnar_strategy=mnar_strategy,\n      mnar_imputed_values=imputed,\n      mnar_affected_features=affected_features,\n      warnings=warnings\n    )\n  )\n}\n\nvarying_terms <- function(meta, covariates, include_batch=TRUE) {\n  terms <- character()\n  if (include_batch && \"batch\" %in% names(meta)) {\n    values <- unique(meta$batch[!is.na(meta$batch) & nzchar(meta$batch)])\n    if (length(values) > 1L) terms <- c(terms, \"batch\")\n  }\n  for (col in covariates) {\n    if (!col %in% names(meta)) next\n    values <- unique(meta[[col]][!is.na(meta[[col]]) & nzchar(as.character(meta[[col]]))])\n    if (length(values) > 1L) terms <- c(terms, col)\n  }\n  unique(terms)\n}\n\nsafe_formula <- function(terms) {\n  if (!length(terms)) return(~ 1)\n  stats::reformulate(terms)\n}\n\ntop_frame <- function(x, n=100L) {\n  if (is.null(x)) return(list())\n  x <- as.data.frame(x, stringsAsFactors=FALSE)\n  if (!nrow(x)) return(list())\n  x <- utils::head(x, n)\n  lapply(seq_len(nrow(x)), function(i) as.list(x[i, , drop=FALSE]))\n}\n\nnonempty_unique <- function(x) unique(as.character(x[!is.na(x) & nzchar(as.character(x))]))\n\nbatch_completely_confounded <- function(meta, target_columns=c(\"condition\",\"timepoint\")) {\n  if (!\"batch\" %in% names(meta)) return(NULL)\n  batches <- nonempty_unique(meta$batch)\n  if (length(batches) <= 1L) return(NULL)\n\n  for (target in target_columns) {\n    if (!target %in% names(meta)) next\n    target_values <- nonempty_unique(meta[[target]])\n    if (length(target_values) <= 1L) next\n    complete <- !is.na(meta$batch) & nzchar(as.character(meta$batch)) &\n      !is.na(meta[[target]]) & nzchar(as.character(meta[[target]]))\n    if (!any(complete)) next\n    tab <- table(meta$batch[complete], meta[[target]][complete])\n    # If no technical series spans two target states, the two effects cannot be\n    # separated. Do not 'correct the batch' and then call the residual biological.\n    if (nrow(tab) > 1L && ncol(tab) > 1L && all(rowSums(tab > 0) <= 1L)) return(target)\n  }\n  NULL\n}\n\nresidualize_nuisance_matrix <- function(x, meta, terms) {\n  x <- as.matrix(x)\n  storage.mode(x) <- \"double\"\n  if (!length(terms)) return(list(matrix=x, status=\"not_needed\", terms=character(), adjusted_features=0L))\n\n  design <- stats::model.matrix(safe_formula(terms), data=meta)\n  if (qr(design)$rank < ncol(design)) {\n    return(list(\n      matrix=x,\n      status=\"blocked\",\n      terms=terms,\n      adjusted_features=0L,\n      message=\"Nuisance-adjustment design matrix is rank-deficient.\"\n    ))\n  }\n\n  out <- x\n  adjusted <- 0L\n  for (j in seq_len(ncol(x))) {\n    y <- x[,j]\n    keep <- is.finite(y) & stats::complete.cases(design)\n    if (sum(keep) <= ncol(design) + 1L) next\n    fit <- try(stats::lm.fit(design[keep,,drop=FALSE], y[keep]), silent=TRUE)\n    if (inherits(fit,\"try-error\")) next\n    residuals <- fit$residuals\n    if (length(residuals) != sum(keep) || !any(is.finite(residuals))) next\n    out[keep,j] <- residuals + mean(y[keep], na.rm=TRUE)\n    adjusted <- adjusted + 1L\n  }\n\n  list(\n    matrix=out,\n    status=if (adjusted > 0L) \"adjusted\" else \"not_estimable\",\n    terms=terms,\n    adjusted_features=adjusted,\n    message=if (adjusted > 0L) \"Known nuisance effects were regressed out feature-wise before multiblock integration.\" else \"No feature had enough complete observations for nuisance adjustment.\"\n  )\n}\n\nprepare_multiblock_integration <- function(blocks, metas, covariates, target_columns=c(\"condition\",\"timepoint\")) {\n  out <- blocks\n  details <- list()\n  for (layer in names(blocks)) {\n    x <- blocks[[layer]]\n    m <- metas[[layer]]\n    common <- intersect(rownames(x), rownames(m))\n    x <- x[common,,drop=FALSE]\n    m <- m[common,,drop=FALSE]\n\n    confounded_target <- batch_completely_confounded(m, target_columns)\n    if (!is.null(confounded_target)) {\n      return(list(\n        status=\"blocked\",\n        blocks=blocks,\n        details=details,\n        message=sprintf(\"%s: technical batch is completely confounded with %s; multiblock integration was not run.\", layer, confounded_target)\n      ))\n    }\n\n    terms <- varying_terms(m, covariates, include_batch=TRUE)\n    adjusted <- residualize_nuisance_matrix(x, m, terms)\n    details[[layer]] <- list(\n      status=adjusted$status,\n      terms=adjusted$terms,\n      adjusted_features=adjusted$adjusted_features,\n      message=adjusted$message\n    )\n    if (identical(adjusted$status, \"blocked\")) {\n      return(list(status=\"blocked\", blocks=blocks, details=details, message=paste(layer, adjusted$message)))\n    }\n    out[[layer]] <- adjusted$matrix\n  }\n\n  list(\n    status=\"ok\",\n    blocks=out,\n    details=details,\n    message=\"Known non-confounded technical series and explicitly selected covariates were adjusted before multiblock integration when estimable.\"\n  )\n}\n\nreactome_current_pathways <- function(identifier_type, species=\"Homo sapiens\") {\n  file_name <- switch(\n    identifier_type,\n    ensembl_gene = \"Ensembl2Reactome_All_Levels.txt\",\n    ensembl_protein = \"Ensembl2Reactome_All_Levels.txt\",\n    uniprot = \"UniProt2Reactome_All_Levels.txt\",\n    NULL\n  )\n  if (is.null(file_name)) return(NULL)\n  url <- paste0(\"https://reactome.org/download/current/\", file_name)\n  tab <- try(utils::read.delim(url, header=FALSE, quote=\"\", comment.char=\"\", stringsAsFactors=FALSE), silent=TRUE)\n  if (inherits(tab, \"try-error\") || ncol(tab) < 6L) return(NULL)\n  tab <- tab[tab[[6]] == species, , drop=FALSE]\n  if (!nrow(tab)) return(NULL)\n  split(as.character(tab[[1]]), paste0(as.character(tab[[2]]), \" | \", as.character(tab[[4]])))\n}\n\nmethod_status <- function(method, status, details=list()) c(list(method=method, status=status), details)\n\n# Passive, local-only runtime inventory recorded with each reference analysis.\n# Package versions are evidence, not an environment lock or replay guarantee.\nreference_runtime_manifest <- function() {\n  wanted <- c(\"DESeq2\",\"edgeR\",\"limma\",\"lmerTest\",\"survival\",\n              \"fgsea\",\"MOFA2\",\"mixOmics\",\"xcms\",\"MsExperiment\",\n              \"Spectra\",\"mzR\",\"BiocParallel\",\"plumber\",\"jsonlite\")\n  available <- vapply(wanted,requireNamespace,logical(1),quietly=TRUE)\n  versions <- lapply(wanted,function(package) {\n    if(!isTRUE(available[[package]]))return(NULL)\n    as.character(utils::packageVersion(package))\n  })\n  names(versions) <- wanted\n  versions <- versions[!vapply(versions,is.null,logical(1))]\n  bioc <- if(requireNamespace(\"BiocManager\",quietly=TRUE)) {\n    tryCatch(as.character(BiocManager::version()),error=function(e) NULL)\n  } else NULL\n  source_names <- c(\"server.R\",\"advanced_methods.R\",\"paired_rnaseq_reference.R\",\n                    \"reference_full_results.R\",\"external_validation.R\")\n  source_files <- file.path(reference_backend_dir,source_names)\n  source_sha256 <- if(requireNamespace(\"digest\",quietly=TRUE) &&\n                    all(file.exists(source_files))) {\n    hashes <- vapply(source_files,function(path)\n      digest::digest(file=path,algo=\"sha256\"),character(1))\n    setNames(as.list(unname(hashes)),source_names)\n  } else NULL\n  list(\n    RVersion=as.character(getRversion()),\n    RPlatform=R.version$platform,\n    BioconductorRelease=bioc,\n    referenceSourceSha256=source_sha256,\n    packageVersions=versions,\n    limitation=\"Captured installed package versions only; not a dependency lock, raw data archive, external database snapshot or reproducible operating-system container.\"\n  )\n}\n\n\nrun_backend_analysis <- function(payload) {\n  protocol <- or_else(payload$protocol, list())\n  data_types <- or_else(payload$dataTypes, list())\n  identifier_types <- or_else(payload$identifierTypes, list())\n  mapping <- or_else(payload$columnMapping, list())\n  covariates <- unlist(or_else(protocol$covariateColumns, character()), use.names=FALSE)\n\n  raw_meta <- read_csv_text(payload$metadataCsv)\n  meta <- canonical_metadata(raw_meta, mapping, covariates)\n  layers <- intersect(c(\"transcriptomics\",\"proteomics\",\"metabolomics\"), names(payload$matrices))\n  if (length(layers) < 1L) stop(\"Reference backend requires at least one omics matrix.\")\n\n  blocks <- list()\n  raw_blocks <- list()\n  assay_contracts <- list()\n  metas <- list()\n  preprocessing <- list()\n  ms_qc_summaries <- list()\n  for (layer in layers) {\n    layer_meta <- meta[meta$omic == layer, , drop=FALSE]\n    if((identical(protocol$analysisIntent,\"confirmatory\") ||\n        identical(protocol$designType,\"paired\")) &&\n       identical(layer,\"transcriptomics\") &&\n       identical(data_types[[layer]],\"raw_counts\"))\n      rnaseq_confirmatory_sample_type_check(layer_meta)\n    expected <- unique(layer_meta$assay_id)\n    x <- matrix_samples_by_features(\n      payload$matrices[[layer]], expected,\n      strict_exact=(identical(protocol$analysisIntent,\"confirmatory\") ||\n        identical(protocol$designType,\"paired\")) &&\n        identical(layer,\"transcriptomics\") &&\n        identical(data_types[[layer]],\"raw_counts\")\n    )\n\n    if (layer == \"metabolomics\") {\n      ms <- apply_ms_qc_reference(x, layer_meta, protocol)\n      x <- ms$matrix\n      layer_meta <- ms$metadata\n      ms_qc_summaries[[layer]] <- ms$summary\n    } else {\n      biological <- vapply(layer_meta$sample_type, canonical_sample_type, character(1)) == \"biological\"\n      if (any(!biological)) {\n        keep_assays <- layer_meta$assay_id[biological]\n        x <- x[rownames(x) %in% keep_assays,,drop=FALSE]\n        layer_meta <- layer_meta[biological,,drop=FALSE]\n      }\n    }\n\n    value_type <- or_else(data_types[[layer]], \"normalized\")\n    assay_contract <- if((identical(protocol$analysisIntent,\"confirmatory\") ||\n        identical(protocol$designType,\"paired\")) &&\n        identical(layer,\"transcriptomics\") &&\n        identical(value_type,\"raw_counts\"))\n      rnaseq_confirmatory_assay_integrity(x, layer_meta) else NULL\n    if(!is.null(assay_contract))assay_contracts[[layer]]<-assay_contract\n    raw_agg <- aggregate_technical_replicates(x, layer_meta, value_type)\n    raw_blocks[[layer]] <- raw_agg$matrix\n\n    prepared <- reference_preprocess_matrix(x, layer, value_type)\n    processed_agg <- aggregate_technical_replicates(prepared$matrix, layer_meta, \"normalized\")\n    blocks[[layer]] <- processed_agg$matrix\n    metas[[layer]] <- processed_agg$metadata\n    preprocessing[[layer]] <- prepared$steps\n  }\n\n  temp <- tempfile(\"pmx_multiomics_\")\n  dir.create(temp, recursive=TRUE)\n  on.exit(unlink(temp, recursive=TRUE, force=TRUE), add=TRUE)\n  methods <- list()\n  ranked <- list()\n  if (length(ms_qc_summaries)) {\n    methods$metabolomics_ms_qc <- method_status(\n      \"R reference metabolomics MS QC\",\n      \"ok\",\n      list(summary=ms_qc_summaries$metabolomics)\n    )\n  }\n\n  objective <- or_else(protocol$objective, \"explore\")\n  design_type <- or_else(protocol$designType, \"independent\")\n  longitudinal <- isTRUE(protocol$longitudinal)\n  outcome_type <- or_else(protocol$outcomeType, \"none\")\n  rna_count_method <- tolower(as.character(or_else(protocol$rnaCountMethod, \"both\")))\n  if (!rna_count_method %in% c(\"auto\",\"both\",\"deseq2\",\"voom\")) rna_count_method <- \"both\"\n  if(objective==\"groups\" && identical(design_type,\"paired\") &&\n     (!\"transcriptomics\"%in%layers ||\n      !identical(data_types[[\"transcriptomics\"]],\"raw_counts\")))\n    stop(\"Paired reference RNA-seq currently requires an uploaded transcriptomics raw-count matrix; other paired models are not silently treated as independent.\",call.=FALSE)\n\n  for (layer in layers) {\n    x <- blocks[[layer]]\n    m <- metas[[layer]]\n    layer_dir <- file.path(temp, layer)\n    dir.create(layer_dir, recursive=TRUE)\n\n    if (objective == \"groups\" && design_type %in% c(\"independent\",\"paired\") && !longitudinal &&\n        layer == \"transcriptomics\" && identical(data_types[[layer]], \"raw_counts\")) {\n      pairing <- NULL\n      if(identical(design_type,\"paired\")){\n        pairing <- paired_rnaseq_design(raw_blocks[[layer]],m,protocol,covariates)\n        m <- pairing$metadata\n        form <- pairing$design_formula\n        contrast <- pairing$contrast\n      } else {\n        terms <- c(varying_terms(m, covariates), \"condition\")\n        groups <- sort(unique(m$condition[nzchar(m$condition)]))\n        if (length(groups) >= 2L) m$condition <- factor(m$condition, levels=groups)\n        form <- safe_formula(terms)\n        contrast <- if(identical(protocol$analysisIntent,\"confirmatory\")) {\n          rnaseq_confirmatory_explicit_contrast(protocol,groups)\n        } else if(length(groups)==2L) c(\"condition\",groups[2],groups[1]) else NULL\n      }\n      run_deseq <- rna_count_method %in% c(\"auto\",\"both\",\"deseq2\")\n      run_voom <- rna_count_method %in% c(\"auto\",\"both\",\"voom\")\n      fit_deseq <- NULL\n      fit_voom <- NULL\n\n      if (run_deseq) {\n        if (requireNamespace(\"DESeq2\", quietly=TRUE)) {\n          fit_deseq <- try(run_deseq2_counts(\n            raw_blocks[[layer]], m, layer_dir, form, contrast,\n            # The original R1 confirmatory preflight explicitly prohibits\n            # repeated subject IDs. Paired fits instead use the separate,\n            # strict paired_rnaseq_design() preflight above; never bypass it.\n            confirmatory_contract=identical(protocol$analysisIntent,\"confirmatory\") &&\n              !identical(design_type,\"paired\")\n          ), silent=TRUE)\n          if (!inherits(fit_deseq,\"try-error\")) {\n            methods[[paste0(layer,\"_differential_deseq2\")]] <- method_status(\"DESeq2\",\"ok\",c(list(top=top_frame(fit_deseq$results),confirmatoryInputContract=if(!is.null(pairing))pairing$contract else fit_deseq$confirmatory_input_contract,assayIntegrityContract=assay_contracts[[layer]],pairedDesignContract=if(!is.null(pairing))pairing$contract else NULL),reference_complete_table(fit_deseq$results,original_features=ncol(raw_blocks[[layer]]))))\n          } else {\n            methods[[paste0(layer,\"_differential_deseq2\")]] <- method_status(\"DESeq2\",\"error\",list(message=as.character(fit_deseq)))\n          }\n        } else {\n          methods[[paste0(layer,\"_differential_deseq2\")]] <- method_status(\"DESeq2\",\"unavailable\",list(message=\"DESeq2 is not installed.\"))\n        }\n      }\n\n      if (run_voom) {\n        if (requireNamespace(\"edgeR\", quietly=TRUE) && requireNamespace(\"limma\", quietly=TRUE)) {\n          fit_voom <- try(run_voom_counts(raw_blocks[[layer]], m, layer_dir, form), silent=TRUE)\n          if (!inherits(fit_voom,\"try-error\")) {\n            methods[[paste0(layer,\"_differential_voom\")]] <- method_status(\"edgeR + limma-voom\",\"ok\",c(list(top=top_frame(fit_voom$results),pairedDesignContract=if(!is.null(pairing))pairing$contract else NULL),reference_complete_table(fit_voom$results,original_features=ncol(raw_blocks[[layer]]))))\n          } else {\n            methods[[paste0(layer,\"_differential_voom\")]] <- method_status(\"edgeR + limma-voom\",\"error\",list(message=as.character(fit_voom)))\n          }\n        } else {\n          methods[[paste0(layer,\"_differential_voom\")]] <- method_status(\"edgeR + limma-voom\",\"unavailable\",list(message=\"edgeR and limma are required for voom.\"))\n        }\n      }\n\n      deseq_ok <- !is.null(fit_deseq) && !inherits(fit_deseq,\"try-error\")\n      voom_ok <- !is.null(fit_voom) && !inherits(fit_voom,\"try-error\")\n      if (deseq_ok && voom_ok) {\n        concordance <- compare_rnaseq_methods(fit_deseq$results, fit_voom$results)\n        methods[[paste0(layer,\"_differential_concordance\")]] <- method_status(\n          \"DESeq2 vs edgeR/limma-voom concordance\",\n          concordance$status,\n          list(summary=concordance)\n        )\n      }\n\n      if (deseq_ok) {\n        methods[[paste0(layer,\"_differential\")]] <- method_status(\n          if (voom_ok) \"DESeq2 primary + edgeR/limma-voom sensitivity\" else \"DESeq2\",\n          \"ok\",\n          list(top=top_frame(fit_deseq$results),\n               pairedDesignContract=if(!is.null(pairing))pairing$contract else NULL)\n        )\n        if (\"stat\" %in% names(fit_deseq$results)) {\n          stat <- fit_deseq$results$stat\n          names(stat) <- fit_deseq$results$feature\n          ranked[[layer]] <- stat\n        }\n      } else if (voom_ok) {\n        methods[[paste0(layer,\"_differential\")]] <- method_status(\"edgeR + limma-voom\",\"ok\",list(top=top_frame(fit_voom$results),\n          pairedDesignContract=if(!is.null(pairing))pairing$contract else NULL))\n        if (\"t\" %in% names(fit_voom$results)) {\n          stat <- fit_voom$results$t\n          names(stat) <- fit_voom$results$feature\n          ranked[[layer]] <- stat\n        }\n      } else {\n        methods[[paste0(layer,\"_differential\")]] <- method_status(\n          \"RNA-seq count differential analysis\",\n          \"unavailable\",\n          list(message=\"No requested reference RNA-seq count method completed successfully.\")\n        )\n      }\n    } else if (objective == \"groups\" && design_type == \"independent\" && !longitudinal) {\n      if (requireNamespace(\"limma\", quietly=TRUE)) {\n        groups <- sort(unique(m$condition[nzchar(m$condition)]))\n        if (length(groups) == 2L) {\n          m$condition <- factor(m$condition, levels=groups)\n          terms <- c(varying_terms(m, covariates), \"condition\")\n          fit <- try(run_limma_matrix(x, m, layer_dir, safe_formula(terms)), silent=TRUE)\n          if (!inherits(fit,\"try-error\")) {\n            methods[[paste0(layer,\"_differential\")]] <- method_status(\"limma\",\"ok\",c(list(top=top_frame(fit$results)),reference_complete_table(fit$results,original_features=ncol(x))))\n            if (\"t\" %in% names(fit$results)) {\n              stat <- fit$results$t\n              names(stat) <- fit$results$feature\n              ranked[[layer]] <- stat\n            }\n          } else {\n            methods[[paste0(layer,\"_differential\")]] <- method_status(\"limma\",\"error\",list(message=as.character(fit)))\n          }\n        }\n      } else {\n        methods[[paste0(layer,\"_differential\")]] <- method_status(\"limma\",\"unavailable\",list(message=\"limma is not installed.\"))\n      }\n    }\n\n    if (objective == \"outcome\" && identical(outcome_type, \"survival\")) {\n      if (requireNamespace(\"survival\",quietly=TRUE)) {\n        survival_terms <- varying_terms(m,covariates,include_batch=FALSE)\n        fit <- try(run_cox_survival_reference(\n          x, m, file.path(layer_dir,\"cox\"),\n          covariates=survival_terms,\n          ties=\"efron\"\n        ),silent=TRUE)\n        methods[[paste0(layer,\"_survival\")]] <- if (!inherits(fit,\"try-error\")) {\n          method_status(\"R survival::coxph Efron + cox.zph\", \"ok\", list(\n            top=top_frame(fit$results),\n            referenceTable=reference_complete_table(fit$results,original_features=ncol(x)),\n            summary=fit$summary,\n            note=\"R reference fitted; cox.zph and censoring assumptions still require independent review. No automatic confirmatory certificate.\"\n          ))\n        } else {\n          method_status(\"R survival::coxph Efron + cox.zph\", \"blocked\", list(\n            message=as.character(fit),\n            note=\"Survival reference requires one independent sample per subject, valid times/events and adequate events per covariate.\"\n          ))\n        }\n      } else {\n        methods[[paste0(layer,\"_survival\")]] <- method_status(\n          \"R survival::coxph Efron + cox.zph\",\"unavailable\",\n          list(message=\"R survival package not installed.\")\n        )\n      }\n    }\n\n    if ((objective == \"time\" || longitudinal || design_type == \"repeated\")) {\n      key <- paste0(layer,\"_longitudinal\")\n      if (!requireNamespace(\"lmerTest\", quietly=TRUE)) {\n        methods[[key]] <- method_status(\"R lmerTest explicit group-by-time\", \"unavailable\",\n          list(message=\"lmerTest (and lme4) is not installed.\"))\n      } else {\n        # Explicitly refuse ambiguous time labels, condition switching,\n        # non-identifiable contrasts, and missing visits before fitting.\n        attempt <- try({\n          parsed <- parse_longitudinal_time(m$timepoint)\n          m$time <- parsed$time\n          design <- validate_longitudinal_reference_design(m)\n          nuisances <- varying_terms(m,covariates)\n          nuisances <- setdiff(nuisances,c(\"condition\",\"time\",\"timepoint\"))\n          fixed <- paste(c(\"condition * time\",nuisances),collapse=\" + \")\n          fit <- run_lmer_matrix(x,m,layer_dir,\n            fixed_formula=fixed,subject_column=\"subject_id\",\n            interaction_term=design$contrast,random_slope=\"auto\")\n          list(fit=fit,timeScale=parsed$timeScale,\n               summary=attr(fit,\"design_summary\"))\n        },silent=TRUE)\n        if(inherits(attempt,\"try-error\")) {\n          methods[[key]] <- method_status(\"R lmerTest explicit group-by-time\",\"blocked\",\n            list(message=as.character(attempt),\n              note=\"No arbitrary coefficient selection or group/time parsing fallback is permitted.\"))\n        } else {\n          fit <- attempt$fit\n          estimable <- sum(is.finite(fit$p_value))\n          methods[[key]] <- method_status(\n            \"R lmerTest group-by-time slope difference\",\n            if(estimable>0L)\"ok\" else \"blocked\",\n            list(top=top_frame(fit),\n                 referenceTable=reference_complete_table(fit,original_features=ncol(x)),\n                 summary=c(attempt$summary,list(timeScale=attempt$timeScale)),\n                 note=\"Feature-level errors, singular fits and random-slope fallbacks are disclosed. BH includes all submitted features; independent scientific design review remains mandatory.\")\n          )\n          if(estimable>0L) {\n            valid <- is.finite(fit$statistic)\n            stat <- fit$statistic[valid]\n            names(stat) <- fit$feature[valid]\n            ranked[[layer]] <- stat\n          }\n        }\n      }\n    }\n  }\n\n  # Multiblock methods receive nuisance-adjusted matrices only when the\n  # adjustment is identifiable. Complete batch/biology confounding blocks the\n  # method instead of silently removing biology together with batch.\n  explore_blocks <- NULL\n  explore_adjustment <- NULL\n  if (objective == \"explore\" && length(layers) == 1L) {\n    methods$single_omic_exploration <- method_status(\n      \"Single-omics browser PCA\",\n      \"not_applicable\",\n      list(message=\"Single-omics exploratory PCA is computed in the browser. MOFA2 needs at least two omics layers.\")\n    )\n  }\n  if (objective == \"explore\" && length(layers) >= 2L) {\n    prepared_integration <- prepare_multiblock_integration(\n      blocks,\n      metas,\n      covariates,\n      target_columns=c(\"condition\",\"timepoint\")\n    )\n    explore_adjustment <- prepared_integration\n    if (!identical(prepared_integration$status, \"ok\")) {\n      methods$mofa2 <- method_status(\n        \"MOFA2\",\n        \"blocked\",\n        list(message=prepared_integration$message, nuisance_adjustment=prepared_integration$details)\n      )\n    } else {\n      explore_blocks <- prepared_integration$blocks\n      mofa_input <- try(mofa2_input_preflight(explore_blocks),silent=TRUE)\n      if (inherits(mofa_input,\"try-error\")) {\n        methods$mofa2 <- method_status(\"MOFA2\",\"blocked\",\n          list(message=as.character(mofa_input),\n               nuisance_adjustment=prepared_integration$details,\n               note=\"No silent removal of subjects missing entire omics views. Align cohorts or use a validated missing-view model.\"))\n      } else if (requireNamespace(\"MOFA2\",quietly=TRUE)) {\n        fit <- try(run_mofa2_blocks(explore_blocks, file.path(temp,\"mofa2\"), factors=5L),silent=TRUE)\n        methods$mofa2 <- if (!inherits(fit,\"try-error\")) {\n          method_status(\"MOFA2\",\"ok\",list(summary=fit$summary,nuisance_adjustment=prepared_integration$details))\n        } else {\n          method_status(\"MOFA2\",\"error\",list(message=as.character(fit),nuisance_adjustment=prepared_integration$details))\n        }\n      } else {\n        methods$mofa2 <- method_status(\"MOFA2\",\"unavailable\",\n          list(message=\"MOFA2 is not installed.\",inputAudit=mofa_input,\n               nuisance_adjustment=prepared_integration$details))\n      }\n    }\n  }\n\n  supervised_target <- NULL\n  supervised_target_column <- NULL\n  common_samples <- Reduce(intersect, lapply(metas, rownames))\n  if (length(common_samples)) {\n    if (objective == \"groups\") {\n      supervised_target <- setNames(metas[[1]][common_samples,\"condition\"], common_samples)\n      supervised_target_column <- \"condition\"\n    } else if (objective == \"outcome\" && outcome_type %in% c(\"binary\",\"multiclass\")) {\n      supervised_target <- setNames(metas[[1]][common_samples,\"outcome\"], common_samples)\n      supervised_target_column <- \"outcome\"\n    }\n  }\n  if (length(layers) >= 2L && !is.null(supervised_target) && length(unique(supervised_target[nzchar(supervised_target)])) >= 2L) {\n    # A shared sample may be represented in several omics. Conflicting\n    # group/outcome labels must block supervised integration entirely.\n    label_consistent <- all(vapply(layers,function(layer) {\n      values <- metas[[layer]][common_samples,supervised_target_column]\n      length(values)==length(common_samples) &&\n        !anyNA(values) &&\n        identical(as.character(values),as.character(supervised_target[common_samples]))\n    },logical(1)))\n    if (!label_consistent) {\n      reason <- \"Same biological sample has inconsistent or missing group/outcome labels across omics. Reconcile the sample sheet before supervised integration.\"\n      methods$diablo <- method_status(\"mixOmics DIABLO\",\"blocked\",list(message=reason))\n      if (isTRUE(protocol$validateDiabloHoldout))\n        methods$diablo_heldout <- method_status(\"DIABLO subject-heldout validation\",\"blocked\",\n          list(message=reason))\n    } else {\n    target_columns <- unique(c(supervised_target_column, if (supervised_target_column != \"condition\") \"condition\" else character()))\n    prepared_supervised <- prepare_multiblock_integration(blocks, metas, covariates, target_columns=target_columns)\n    if (!identical(prepared_supervised$status, \"ok\")) {\n      methods$diablo <- method_status(\n        \"mixOmics DIABLO\",\n        \"blocked\",\n        list(message=prepared_supervised$message, nuisance_adjustment=prepared_supervised$details)\n      )\n      if(isTRUE(protocol$validateDiabloHoldout))\n        methods$diablo_heldout <- method_status(\"DIABLO subject-heldout validation\",\"blocked\",\n          list(message=prepared_supervised$message))\n    } else if (requireNamespace(\"mixOmics\", quietly=TRUE)) {\n      fit <- try(run_diablo_blocks(\n        prepared_supervised$blocks,\n        supervised_target,\n        file.path(temp,\"diablo\"),\n        ncomp=2L,\n        tune=TRUE,\n        nrepeat=3L\n      ), silent=TRUE)\n      methods$diablo <- if (!inherits(fit,\"try-error\")) {\n        method_status(\"mixOmics DIABLO\",\"ok\",list(summary=fit$summary, nuisance_adjustment=prepared_supervised$details))\n      } else {\n        method_status(\"mixOmics DIABLO\",\"error\",list(message=as.character(fit), nuisance_adjustment=prepared_supervised$details))\n      }\n      if (isTRUE(protocol$validateDiabloHoldout)) {\n        # Full-cohort tuning/perf() is not a legitimate independent BER.\n        # For holdouts use only as-supplied log data without pre-CV fitted\n        # cohort normalisation, covariate correction or varying batch.\n        reason <- NULL\n        if (!identical(design_type,\"independent\") || longitudinal)\n          reason <- \"Repeated measures or non-independent plans are unsupported.\"\n        if(is.null(reason) && \"metabolomics\" %in% layers)\n          reason <- \"Metabolomics reference preprocessing (MS blanks, pooled QC and drift) is fitted on the cohort before these blocks are created; strict fold-isolated evaluation is not yet available for metabolomics.\"\n        if(is.null(reason) && length(covariates))\n          reason <- \"Selected covariates require training-only nuisance fitting.\"\n        if(is.null(reason) && any(vapply(layers,function(layer)\n             !(as.character(or_else(data_types[[layer]],\"unknown\")) %in%\n               c(\"log_expression\",\"log_intensity\",\"log_abundance\")),logical(1))))\n          reason <- \"Only as-supplied log-intensity/expression/abundance data; no global raw-count or MS preprocessing.\"\n        if(is.null(reason) && any(vapply(layers,function(layer)\n             length(nonempty_unique(metas[[layer]]$batch))>1L,logical(1))))\n          reason <- \"Varying batch must be adjusted using training samples only; unsupported here.\"\n        if(is.null(reason) && any(vapply(layers,function(layer) {\n          m<-metas[[layer]]\n          ids<-intersect(rownames(raw_blocks[[layer]]),rownames(m))\n          length(ids)<32L || anyNA(m[ids,\"subject_id\"]) ||\n            any(!nzchar(as.character(m[ids,\"subject_id\"]))) ||\n            anyDuplicated(as.character(m[ids,\"subject_id\"]))>0L\n        },logical(1))))\n          reason <- \"At least 32 shared independent subjects and one observation per subject in each omic.\"\n        if(is.null(reason)) {\n          shared<-Reduce(intersect,lapply(raw_blocks[layers],rownames))\n          if(!length(shared) || any(vapply(layers,function(layer)\n              !identical(as.character(metas[[layer]][shared,\"subject_id\"]),\n                         as.character(metas[[layers[1]]][shared,\"subject_id\"])),logical(1))))\n            reason <- \"Omic layers do not agree on sample-to-subject identities.\"\n        }\n        if(!is.null(reason)) {\n          methods$diablo_heldout<-method_status(\"DIABLO subject-heldout validation\",\n            \"blocked\",list(message=reason))\n        } else {\n          ev<-try(run_diablo_outer_holdout(raw_blocks[layers],supervised_target,\n              file.path(temp,\"diablo_heldout\"),\n              seeds=c(20261009L,20261010L,20261011L),tune=TRUE),silent=TRUE)\n          methods$diablo_heldout <- if(inherits(ev,\"try-error\")) {\n            method_status(\"DIABLO subject-heldout validation\",\"blocked\",\n              list(message=as.character(ev)))\n          } else {\n            method_status(\"DIABLO subject-heldout validation\",\"ok\",\n              list(summary=ev$summary,\n                note=\"Repeated internal heldouts, training-only filtering/imputation/scaling/tuning, NOT an external cohort.\"))\n          }\n        }\n      }\n    } else {\n      methods$diablo <- method_status(\"mixOmics DIABLO\",\"unavailable\",list(message=\"mixOmics is not installed.\", nuisance_adjustment=prepared_supervised$details))\n      if(isTRUE(protocol$validateDiabloHoldout))\n        methods$diablo_heldout <- method_status(\"DIABLO subject-heldout validation\",\"unavailable\",\n          list(message=\"R mixOmics must be installed for strict subject-heldout validation.\"))\n    }\n    }\n  }\n\n  if (requireNamespace(\"fgsea\", quietly=TRUE) && length(ranked)) {\n    for (layer in names(ranked)) {\n      id_type <- or_else(identifier_types[[layer]], \"unknown\")\n      species <- if (or_else(protocol$organism, \"human\") == \"mouse\") \"Mus musculus\" else \"Homo sapiens\"\n      pathways <- reactome_current_pathways(id_type, species)\n      if (is.null(pathways)) next\n      fit <- try(run_fgsea_ranked(ranked[[layer]], pathways, file.path(temp,paste0(\"fgsea_\",layer))), silent=TRUE)\n      methods[[paste0(layer,\"_fgsea\")]] <- if (!inherits(fit,\"try-error\")) method_status(\"fgsea + Reactome current mapping\",\"ok\",list(top=top_frame(fit))) else method_status(\"fgsea\",\"error\",list(message=as.character(fit)))\n    }\n  }\n\n  packages <- vapply(c(\"DESeq2\",\"edgeR\",\"limma\",\"lmerTest\",\"survival\",\"fgsea\",\"MOFA2\",\"mixOmics\"), requireNamespace, logical(1), quietly=TRUE)\n  list(\n    status=\"ok\",\n    engine=list(\n      name=\"PMx Explain reference R backend\",\n      version=\"1.4.0\",\n      policy=\"Reference methods are eligibility-gated; identifiable nuisance effects are adjusted before multiblock integration and complete technical confounding blocks MOFA2/DIABLO.\"\n    ),\n    analysisMode=if (length(layers) == 1L) \"single_omic\" else \"multiomics\",\n    analysedLayers=layers,\n    applicableMethods=names(methods),\n    methods=methods,\n    preprocessing=preprocessing,\n    packages=as.list(packages),\n    runtime=reference_runtime_manifest()\n  )\n}\n\n#* @filter cors\nfunction(req, res) {\n  # Origin acceptance is enforced by run_backend.R. Do not emit a wildcard\n  # here: a wildcard would make a localhost research-data service callable\n  # from unrelated web pages.\n  res$setHeader(\"Access-Control-Allow-Methods\", \"GET,POST,OPTIONS\")\n  res$setHeader(\"Access-Control-Allow-Headers\", \"Content-Type\")\n  # IMPORTANT: an OPTIONS preflight must reach the outer origin_guard. Early\n  # returning here skipped Access-Control-Allow-Origin for browser JSON POST.\n  plumber::forward()\n}\n\n#* @get /health\n#* @serializer json list(auto_unbox=TRUE)\nfunction() {\n  packages <- vapply(\n    c(\"DESeq2\",\"edgeR\",\"limma\",\"lmerTest\",\"survival\",\"fgsea\",\"MOFA2\",\"mixOmics\",\"xcms\",\"MsExperiment\",\"Spectra\",\"mzR\",\"BiocParallel\"),\n    requireNamespace,\n    logical(1),\n    quietly=TRUE\n  )\n  raw_required <- c(\"xcms\",\"MsExperiment\",\"Spectra\",\"mzR\")\n  list(\n    status=\"ok\",\n    engine=\"PMx Explain reference R backend\",\n    version=\"1.4.0\",\n    packages=as.list(packages),\n    runtime=reference_runtime_manifest(),\n    capabilities=list(\n      reference_analysis=TRUE,\n      frozen_external_validation=TRUE,\n      raw_ms_cli=all(packages[raw_required]),\n      mofa2_orientation_contract=\"mofa2-feature-rows-sample-columns-v2\"\n    )\n  )\n}\n\n#* @post /external-validation\n#* @serializer json list(auto_unbox=TRUE, dataframe=\"rows\", na=\"null\")\nfunction(req, res) {\n  if (!requireNamespace(\"jsonlite\", quietly=TRUE)) {\n    res$status <- 500\n    return(list(status=\"error\", message=\"jsonlite is required by the reference backend.\"))\n  }\n  payload <- try(jsonlite::fromJSON(req$postBody, simplifyVector=TRUE), silent=TRUE)\n  if (inherits(payload, \"try-error\") || !is.list(payload)) {\n    res$status <- 400\n    return(list(status=\"error\", message=\"Invalid JSON payload.\"))\n  }\n  predictions_csv <- payload$predictionsCsv\n  config <- payload$config\n  if (is.null(predictions_csv) || !is.character(predictions_csv) || length(predictions_csv) != 1L || !nzchar(predictions_csv)) {\n    res$status <- 400\n    return(list(status=\"error\", message=\"predictionsCsv must contain the frozen prediction CSV as text.\"))\n  }\n  if (is.null(config) || !is.list(config)) {\n    res$status <- 400\n    return(list(status=\"error\", message=\"config must be a JSON object.\"))\n  }\n\n  allowed <- c(\n    \"outcome_type\", \"prediction_column\", \"outcome_column\", \"prediction_kind\",\n    \"time_column\", \"event_column\", \"probability_columns\", \"independent_cohort\",\n    \"cohort_label\", \"bootstrap_repetitions\", \"seed\"\n  )\n  unknown <- setdiff(names(config), allowed)\n  if (length(unknown)) {\n    res$status <- 400\n    return(list(status=\"error\", message=paste(\"Unknown config field(s):\", paste(unknown, collapse=\", \"))))\n  }\n  if (is.null(config$outcome_type) || !nzchar(as.character(config$outcome_type))) {\n    res$status <- 400\n    return(list(status=\"error\", message=\"config.outcome_type is required.\"))\n  }\n\n  data <- try(read_csv_text(predictions_csv), silent=TRUE)\n  if (inherits(data, \"try-error\") || !nrow(data)) {\n    res$status <- 400\n    return(list(status=\"error\", message=\"The frozen prediction CSV could not be parsed or is empty.\"))\n  }\n\n  result <- try(do.call(validate_external_predictions, c(list(data=data), config)), silent=TRUE)\n  if (inherits(result, \"try-error\")) {\n    res$status <- 422\n    return(list(status=\"error\", message=as.character(result)))\n  }\n  result$input <- list(rows=nrow(data), columns=as.list(names(data)))\n  result\n}\n\n#* @post /run\n#* @serializer json list(auto_unbox=TRUE, dataframe=\"rows\", na=\"null\")\nfunction(req, res) {\n  if (!requireNamespace(\"jsonlite\", quietly=TRUE)) {\n    res$status <- 500\n    return(list(status=\"error\", message=\"jsonlite is required by the reference backend.\"))\n  }\n  payload <- try(jsonlite::fromJSON(req$postBody, simplifyVector=FALSE), silent=TRUE)\n  if (inherits(payload,\"try-error\")) {\n    res$status <- 400\n    return(list(status=\"error\", message=\"Invalid JSON payload.\"))\n  }\n  tryCatch(\n    run_backend_analysis(payload),\n    error=function(e) {\n      res$status <- 422\n      list(status=\"error\", message=conditionMessage(e))\n    }\n  )\n}\n","advanced_methods.R":"# Advanced multi-omics adapters for local/server execution.\n# These functions intentionally use reference R implementations rather than\n# relabelling browser-native PCA/PLS code as MOFA2 or DIABLO.\n#\n# Methodological policy:\n# - deterministic seeds are recorded;\n# - supervised multiblock models are tuned inside repeated CV before final fit;\n# - unsupervised factor analysis refuses clearly underpowered sample counts;\n# - longitudinal models attempt a random slope only when the design can support it;\n# - sensitivity methods are compared, never merged by averaging p-values/q-values.\n\nrequire_namespace <- function(pkg) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    stop(sprintf(\"Package '%s' is required for this advanced method.\", pkg), call. = FALSE)\n  }\n}\n\nvalidate_blocks <- function(blocks, min_samples = 3L) {\n  if (!is.list(blocks) || length(blocks) < 2L) {\n    stop(\"blocks must contain at least two omics matrices.\", call. = FALSE)\n  }\n  if (is.null(names(blocks)) || any(names(blocks) == \"\")) {\n    stop(\"Every block must have a name.\", call. = FALSE)\n  }\n  blocks <- lapply(blocks, function(x) {\n    x <- as.matrix(x)\n    storage.mode(x) <- \"double\"\n    if (is.null(rownames(x))) stop(\"Every block must use sample IDs as row names.\", call. = FALSE)\n    x\n  })\n  common <- Reduce(intersect, lapply(blocks, rownames))\n  if (length(common) < as.integer(min_samples)) {\n    stop(sprintf(\"At least %d samples must be shared across blocks.\", as.integer(min_samples)), call. = FALSE)\n  }\n  lapply(blocks, function(x) x[common, , drop = FALSE])\n}\n\nwrite_matrix_csv <- function(x, path) {\n  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)\n  utils::write.csv(data.frame(sample_id = rownames(x), x, check.names = FALSE), path, row.names = FALSE)\n}\n\nfilter_informative_features <- function(x, min_observed = 3L, max_features = NULL) {\n  x <- as.matrix(x)\n  observed <- colSums(is.finite(x))\n  variances <- vapply(seq_len(ncol(x)), function(j) {\n    values <- x[, j]\n    values <- values[is.finite(values)]\n    if (length(values) < min_observed) return(NA_real_)\n    stats::var(values)\n  }, numeric(1))\n  keep <- observed >= min_observed & is.finite(variances) & variances > 0\n  x <- x[, keep, drop = FALSE]\n  variances <- variances[keep]\n  if (!is.null(max_features) && is.finite(max_features) && ncol(x) > max_features) {\n    order_idx <- order(variances, decreasing = TRUE, na.last = NA)\n    x <- x[, order_idx[seq_len(as.integer(max_features))], drop = FALSE]\n  }\n  x\n}\n\n# Audit before create_mofa(). No silent intersection of unmatched subjects:\n# otherwise the effective population can depend on which views were supplied.\nmofa2_input_preflight <- function(blocks, min_samples=16L,\n                                  max_missing_fraction=0.40) {\n  if(!is.list(blocks) || length(blocks)<2L || is.null(names(blocks)) ||\n     anyNA(names(blocks)) || any(!nzchar(names(blocks))) ||\n     anyDuplicated(names(blocks)))\n    stop(\"MOFA2 requires at least two uniquely named omics layers.\")\n  if(!is.finite(max_missing_fraction) || max_missing_fraction<0 ||\n     max_missing_fraction>=1)\n    stop(\"Invalid MOFA2 missingness safeguard.\")\n  views <- list()\n  subject_sets <- list()\n  for(layer in names(blocks)) {\n    x <- as.matrix(blocks[[layer]])\n    suppressWarnings(storage.mode(x)<-\"double\")\n    ids <- rownames(x)\n    features <- colnames(x)\n    if(is.null(ids) || is.null(features) ||\n       anyNA(ids) || anyNA(features) ||\n       any(!nzchar(ids)) || any(!nzchar(features)) ||\n       anyDuplicated(ids) || anyDuplicated(features))\n      stop(sprintf(\"%s: unique nonempty sample and feature identifiers are required.\",layer))\n    if(nrow(x)<min_samples || ncol(x)<2L)\n      stop(sprintf(\"%s: MOFA2 needs at least %s independent samples and two features.\",\n                   layer,min_samples))\n    if(any(is.infinite(x)) || any(is.nan(x)))\n      stop(sprintf(\"%s: infinite/NaN measurements are not valid missing values.\",layer))\n    missing <- mean(is.na(x))\n    if(!is.finite(missing) || missing>max_missing_fraction)\n      stop(sprintf(\"%s: excessive missing measurements (%.1f%%). Review the assay and missingness mechanism.\",\n                   layer,100*missing))\n    subject_sets[[layer]] <- ids\n    views[[layer]] <- list(\n      samples=nrow(x),originalFeatures=ncol(x),\n      missingFraction=missing,\n      finiteFeatures=sum(colSums(is.finite(x))>=3L),\n      note=\"Latent variance can reflect technical nuisance effects; MOFA2 factors are descriptive, not causal findings.\"\n    )\n  }\n  reference <- subject_sets[[1]]\n  if(any(vapply(subject_sets,function(ids)\n       !setequal(ids,reference),logical(1))))\n    stop(\"MOFA2 views have different sample sets. This backend does not model missing whole views: never silently discard unpaired subjects.\")\n  list(status=\"eligible_for_exploration\",\n       views=views,nSharedSubjects=length(reference),\n       maxMissingFraction=max_missing_fraction,\n       limitations=\"Same subject sets and low missingness do not establish MAR. Batch, biological identity, latent-factor number and stability need independent audit.\")\n}\n\n# Input matrices throughout PMx are sample × feature; MOFA2's *list of\n# matrices* interface is feature × sample. Preserve the explicit biological\n# sample IDs as MOFA2 column names and align both views identically.\nmofa2_orient_reference_matrices <- function(blocks) {\n  mofa2_input_preflight(blocks)\n  ids <- rownames(blocks[[1]])\n  reference <- lapply(blocks,function(z) {\n    z <- as.matrix(z)\n    storage.mode(z) <- \"double\"\n    t(z[ids,,drop=FALSE])\n  })\n  if(any(vapply(reference,function(z)\n       !identical(colnames(z),ids),logical(1))))\n    stop(\"MOFA2 biological subject orientation or order is inconsistent.\")\n  reference\n}\n\nrun_mofa2_blocks <- function(\n  blocks,\n  output_dir,\n  factors = 5L,\n  seed = 20260924L,\n  convergence_mode = \"medium\",\n  min_samples = 16L,\n  max_features_per_block = NULL\n) {\n  # Data validity must be established before the reference package is loaded,\n  # so unsupported sample-set loss never appears as an installation error.\n  input_audit <- mofa2_input_preflight(blocks,min_samples=min_samples)\n  require_namespace(\"MOFA2\")\n  blocks <- validate_blocks(blocks, min_samples = min_samples)\n  raw_feature_counts <- vapply(blocks, ncol, integer(1))\n  blocks <- lapply(blocks, filter_informative_features, max_features = max_features_per_block)\n  if (any(vapply(blocks, ncol, integer(1)) < 2L)) {\n    stop(\"MOFA2 requires at least two informative non-constant features in every retained block.\", call. = FALSE)\n  }\n\n  # MOFA2's own guidance stresses adequate normalisation, removal of known\n  # technical effects and enough samples. The backend handles known technical\n  # series upstream; here we additionally scale views so a high-variance assay\n  # does not dominate merely because of measurement scale.\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  set.seed(seed)\n  n_samples <- nrow(blocks[[1]])\n  factors <- max(1L, min(as.integer(factors), 10L, max(1L, n_samples - 2L)))\n\n  reference_matrices <- mofa2_orient_reference_matrices(blocks)\n  model <- MOFA2::create_mofa(reference_matrices)\n  data_options <- MOFA2::get_default_data_options(model)\n  model_options <- MOFA2::get_default_model_options(model)\n  train_options <- MOFA2::get_default_training_options(model)\n  if (\"scale_views\" %in% names(data_options)) data_options$scale_views <- TRUE\n  model_options$num_factors <- factors\n  train_options$seed <- as.integer(seed)\n  train_options$convergence_mode <- convergence_mode\n  train_options$verbose <- FALSE\n\n  model <- MOFA2::prepare_mofa(\n    model,\n    data_options = data_options,\n    model_options = model_options,\n    training_options = train_options\n  )\n  trained <- MOFA2::run_mofa(\n    model,\n    outfile = file.path(output_dir, \"mofa_model.hdf5\"),\n    use_basilisk = TRUE\n  )\n\n  factors_df <- MOFA2::get_factors(trained, factors = \"all\", as.data.frame = TRUE)\n  weights_df <- MOFA2::get_weights(trained, views = \"all\", factors = \"all\", as.data.frame = TRUE)\n  utils::write.csv(factors_df, file.path(output_dir, \"mofa_factors.csv\"), row.names = FALSE)\n  utils::write.csv(weights_df, file.path(output_dir, \"mofa_weights.csv\"), row.names = FALSE)\n\n  variance_explained <- try(MOFA2::calculate_variance_explained(trained), silent = TRUE)\n  if (!inherits(variance_explained, \"try-error\")) {\n    saveRDS(variance_explained, file.path(output_dir, \"mofa_variance_explained.rds\"))\n  }\n\n  summary <- list(\n    method = \"MOFA2\",\n    seed = as.integer(seed),\n    samples = n_samples,\n    factors_requested = as.integer(factors),\n    inputAudit = input_audit,\n    matrixOrientation = \"feature_rows_subject_columns_for_MOFA2\",\n    implementationContract = \"mofa2-feature-rows-sample-columns-v2\",\n    subjectIdentityPreserved = identical(colnames(reference_matrices[[1]]),rownames(blocks[[1]])),\n    factorStatus = \"descriptive_latent_covariance_not_validated_biomarker\",\n    blocks_before_filtering = raw_feature_counts,\n    blocks_after_filtering = vapply(blocks, ncol, integer(1)),\n    view_scaling = isTRUE(data_options$scale_views),\n    guardrails = list(\n      minimum_shared_samples = as.integer(min_samples),\n      removed_constant_or_unobserved_features = TRUE,\n      known_technical_effects_expected_to_be_handled_upstream = TRUE,\n      interpretation = \"Unsupervised latent factors describe covariance; they are not causal mechanisms or validated biomarkers.\"\n    )\n  )\n  saveRDS(summary, file.path(output_dir, \"mofa_summary.rds\"))\n  invisible(list(model = trained, summary = summary, variance_explained = variance_explained))\n}\n\nmake_keepx_grid <- function(n_features) {\n  n_features <- as.integer(n_features)\n  if (n_features <= 1L) return(1L)\n  candidates <- unique(pmin(n_features, c(2L, 5L, 10L, 20L, 50L, max(2L, round(n_features * 0.10)))))\n  candidates <- sort(unique(as.integer(candidates[candidates >= 1L & candidates <= n_features])))\n  if (length(candidates) < 2L) candidates <- sort(unique(c(1L, n_features)))\n  candidates\n}\n\nnormalise_keepx <- function(keepX, blocks, ncomp) {\n  if (is.null(keepX)) {\n    return(lapply(blocks, function(x) rep(min(20L, max(1L, ncol(x))), ncomp)))\n  }\n  out <- keepX\n  for (view in names(blocks)) {\n    values <- as.integer(out[[view]])\n    if (!length(values)) values <- min(20L, max(1L, ncol(blocks[[view]])))\n    values <- pmax(1L, pmin(values, ncol(blocks[[view]])))\n    if (length(values) < ncomp) values <- c(values, rep(tail(values, 1), ncomp - length(values)))\n    out[[view]] <- values[seq_len(ncomp)]\n  }\n  out[names(blocks)]\n}\n\nsafe_perf_summary <- function(perf) {\n  if (is.null(perf) || inherits(perf, \"try-error\")) return(NULL)\n  error_rate <- perf$error.rate\n  if (is.null(error_rate)) {\n    return(list(\n      status = \"available\",\n      note = \"Performance object saved; compact BER extraction unavailable for this mixOmics version. Internal cross-validation is not external validation.\"\n    ))\n  }\n  ber <- NULL\n  if (is.list(error_rate) && !is.null(error_rate$BER)) ber <- error_rate$BER\n  if (is.null(ber) && is.list(error_rate) && !is.null(error_rate$WeightedVote) && !is.null(error_rate$WeightedVote$BER)) ber <- error_rate$WeightedVote$BER\n  numeric_ber <- suppressWarnings(as.numeric(unlist(ber)))\n  numeric_ber <- numeric_ber[is.finite(numeric_ber)]\n  list(\n    status = \"available\",\n    ber_values_extracted = length(numeric_ber),\n    ber_median = if (length(numeric_ber)) stats::median(numeric_ber) else NA_real_,\n    ber_mean = if (length(numeric_ber)) mean(numeric_ber) else NA_real_,\n    ber_min = if (length(numeric_ber)) min(numeric_ber) else NA_real_,\n    ber_max = if (length(numeric_ber)) max(numeric_ber) else NA_real_,\n    note = \"These BER values summarise repeated internal cross-validation on the same cohort used for model tuning. They are descriptive internal-validation diagnostics, not an unbiased external performance estimate.\"\n  )\n}\n\n\n# Strict subject-level outer evaluation, separate from tuning/perf() on the\n# development cohort. Only accepts log-valued as-supplied matrices; all filters,\n# imputation, centering and standardisation are fit on TRAINING samples only.\n# This is a repeated internal held-out validation, NOT external replication.\nprepare_diablo_holdout_split <- function(blocks, outcome, seed=20261009L,\n                                         test_fraction=0.25,\n                                         max_features_per_block=500L) {\n  if(!is.list(blocks) || length(blocks)<2L || is.null(names(blocks)) ||\n     any(!nzchar(names(blocks))) || anyDuplicated(names(blocks)))\n    stop(\"Holdout DIABLO needs >=2 uniquely named omic blocks.\")\n  blocks <- lapply(blocks,function(z) {\n    z <- as.matrix(z)\n    storage.mode(z) <- \"double\"\n    if(is.null(rownames(z))||anyNA(rownames(z))||anyDuplicated(rownames(z)) ||\n       any(!nzchar(rownames(z))) || is.null(colnames(z))||\n       anyDuplicated(colnames(z)) || any(!nzchar(colnames(z))))\n      stop(\"Holdout DIABLO requires unique subject/sample and feature identifiers.\")\n    z\n  })\n  common <- Reduce(intersect,lapply(blocks,rownames))\n  if(length(common)<32L)\n    stop(\"Holdout DIABLO requires >=32 shared independent subjects.\")\n  blocks <- lapply(blocks,function(z)z[common,,drop=FALSE])\n  if(is.null(names(outcome))||anyDuplicated(names(outcome)) ||\n     anyNA(outcome[common])||any(!nzchar(as.character(outcome[common]))))\n    stop(\"Holdout labels must be uniquely named, complete and match every shared subject.\")\n  y <- droplevels(factor(outcome[common]))\n  if(nlevels(y)!=2L || min(table(y))<12L)\n    stop(\"Holdout DIABLO currently supports 2 classes with >=12 independent subjects per class.\")\n  if(!is.finite(test_fraction)||test_fraction<0.15||test_fraction>0.40)\n    stop(\"Holdout test fraction outside supported range.\")\n  set.seed(as.integer(seed))\n  test <- unlist(lapply(split(seq_along(common),y),function(ix) {\n    size <- max(3L,as.integer(round(length(ix)*test_fraction)))\n    sample(ix,size=size,replace=FALSE)\n  }),use.names=FALSE)\n  train <- setdiff(seq_along(common),test)\n  if(length(intersect(train,test))||length(unique(c(train,test)))!=length(common))\n    stop(\"Train and holdout subjects are not disjoint and exhaustive.\")\n  if(min(table(y[train]))<8L || min(table(y[test]))<3L)\n    stop(\"Insufficient class support after subject-level partition.\")\n  recipes <- list()\n  train_blocks <- list()\n  test_blocks <- list()\n  for(layer in names(blocks)) {\n    z <- blocks[[layer]]\n    tr <- z[train,,drop=FALSE]\n    te <- z[test,,drop=FALSE]\n    # Fold-specific feature selection: no full-cohort variance or missingness.\n    observed <- colSums(is.finite(tr))\n    missing_fraction <- 1-observed/nrow(tr)\n    variance <- vapply(seq_len(ncol(tr)),function(j) {\n      v <- tr[,j];v <- v[is.finite(v)]\n      if(length(v)<3L)return(NA_real_)\n      stats::var(v)\n    },numeric(1))\n    available <- which(observed>=8L & missing_fraction<=0.25 &\n                         is.finite(variance)&variance>1e-12)\n    if(length(available)<2L)\n      stop(paste(\"Insufficient train-only informative features:\",layer))\n    if(length(available)>max_features_per_block)\n      available<-available[order(variance[available],decreasing=TRUE,\n                               na.last=NA)[seq_len(max_features_per_block)]]\n    tr <- tr[,available,drop=FALSE]\n    te <- te[,available,drop=FALSE]\n    medians <- apply(tr,2,stats::median,na.rm=TRUE)\n    for(j in seq_len(ncol(tr))) {\n      tr[!is.finite(tr[,j]),j] <- medians[j]\n      te[!is.finite(te[,j]),j] <- medians[j]\n    }\n    means <- colMeans(tr)\n    sd_train <- apply(tr,2,stats::sd)\n    if(any(!is.finite(sd_train))||any(sd_train<=1e-12))\n      stop(\"Non-identifiable training-only scaling.\")\n    tr <- sweep(sweep(tr,2,means,\"-\"),2,sd_train,\"/\")\n    te <- sweep(sweep(te,2,means,\"-\"),2,sd_train,\"/\")\n    if(any(!is.finite(tr))||any(!is.finite(te)))\n      stop(\"Non-finite fold-local omics values.\")\n    train_blocks[[layer]] <- tr\n    test_blocks[[layer]] <- te\n    recipes[[layer]] <- list(\n      featureNames=colnames(tr),\n      medians=medians,\n      means=means,\n      standardDeviations=sd_train,\n      fittedOn=\"training_subjects_only\"\n    )\n  }\n  names_y <- as.character(y)\n  list(\n    train=train_blocks,test=test_blocks,\n    y_train=factor(names_y[train],levels=levels(y)),\n    y_test=factor(names_y[test],levels=levels(y)),\n    trainIds=common[train],testIds=common[test],\n    trainIndices=train,testIndices=test,\n    recipes=recipes,\n    seed=as.integer(seed),\n    boundary=\"Repeated cohort holdout with fold-local preprocessing, not independent external validation.\"\n  )\n}\n\n# Compare selected feature identities, never their unstable sign/order or scores.\n# Repeated train/test splits overlap; this is a descriptive repeatability measure\n# and not an independent sampling-based confidence interval.\ndiablo_selection_stability <- function(selected_by_split) {\n  if(!is.list(selected_by_split)||length(selected_by_split)<2L)\n    stop(\"DIABLO stability requires >=2 successful predeclared folds.\")\n  blocks<-names(selected_by_split[[1]])\n  if(is.null(blocks)||length(blocks)<2L||anyDuplicated(blocks)||\n     any(!nzchar(blocks)) ||\n     any(vapply(selected_by_split,function(fold)\n       !setequal(names(fold),blocks),logical(1))))\n    stop(\"Different omics blocks between DIABLO stability folds.\")\n  out<-list()\n  for(view in blocks) {\n    sets<-lapply(selected_by_split,function(fold) {\n      vals<-as.character(fold[[view]])\n      if(!length(vals)||anyNA(vals)||any(!nzchar(vals)))\n        stop(paste(\"Missing selected features for\",view))\n      unique(vals)\n    })\n    pairs<-utils::combn(seq_along(sets),2L)\n    jaccard<-vapply(seq_len(ncol(pairs)),function(j) {\n      a<-sets[[pairs[1,j]]]; b<-sets[[pairs[2,j]]]\n      length(intersect(a,b))/length(union(a,b))\n    },numeric(1))\n    tab<-sort(table(unlist(sets,use.names=FALSE)),decreasing=TRUE)\n    out[[view]]<-list(\n      meanPairwiseJaccard=unname(mean(jaccard)),\n      minPairwiseJaccard=unname(min(jaccard)),\n      maxPairwiseJaccard=unname(max(jaccard)),\n      nPairwiseComparisons=length(jaccard),\n      nDistinctSelected=length(tab),\n      nSelectedPerFold=as.integer(lengths(sets)),\n      frequency=as.list(stats::setNames(as.numeric(tab)/length(sets),names(tab))),\n      repeatedlySelected=as.character(names(tab)[as.numeric(tab)>=2L]),\n      limitation=\"Repeated folds share original subjects; selection frequencies and Jaccard are internal exploratory stability, not externally validated biomarkers.\"\n    )\n  }\n  out\n}\n\n# mixOmics::selectVar() returns named variables in version-dependent slots.\n# Fail rather than counting all feature loadings or unmatched identifiers.\nselected_diablo_features <- function(model,view,training_features) {\n  # For block.splsda, selectVar(model, comp=1) returns a list indexed\n  # by VIEW. Passing block=view can still return that outer list; reading\n  # $name on the outer object silently fails in affected mixOmics releases.\n  selected <- mixOmics::selectVar(model,comp=1L)\n  if(!is.list(selected) || is.null(selected[[view]]))\n    stop(paste(\"mixOmics selectVar lacks block:\",view))\n  choice <- selected[[view]]\n  ids <- as.character(unlist(choice$name,use.names=FALSE))\n  if(!length(ids) && (is.matrix(choice$value)||is.data.frame(choice$value)))\n    ids <- rownames(choice$value)\n  ids <- unique(as.character(ids))\n  if(!length(ids)||anyNA(ids)||any(!nzchar(ids)) ||\n     any(!ids %in% training_features))\n    stop(paste(\"mixOmics selected features cannot be matched to train-only names:\",view))\n  ids\n}\n\n# The model is refit inside each outer split; any tuning is restricted to\n# training subjects. Invalid folds fail the WHOLE benchmark, never silently\n# reduce the denominator and make performance look better.\nrun_diablo_outer_holdout <- function(blocks,outcome,output_dir,\n                                     seeds=c(20261009L,20261010L,20261011L),\n                                     tune=TRUE) {\n  require_namespace(\"mixOmics\")\n  if(length(seeds)<2L||anyDuplicated(seeds))stop(\"Need >=2 distinct predeclared outer seeds.\")\n  all_rows <- list()\n  summaries <- list()\n  selections <- list()\n  for(index in seq_along(seeds)) {\n    split <- prepare_diablo_holdout_split(blocks,outcome,seed=seeds[index])\n    ncomp <- 1L\n    design <- matrix(0.1,length(split$train),length(split$train),\n      dimnames=list(names(split$train),names(split$train)))\n    diag(design) <- 0\n    keep <- lapply(split$train,function(z)min(10L,ncol(z)))\n    names(keep) <- names(split$train)\n    if(isTRUE(tune)) {\n      grid <- lapply(split$train,function(z)sort(unique(pmin(ncol(z),c(2L,5L,10L)))))\n      if(all(lengths(grid)>=2L)) {\n        set.seed(as.integer(seeds[index]))\n        trained <- mixOmics::tune.block.splsda(\n          X=split$train,Y=split$y_train,ncomp=ncomp,\n          test.keepX=grid,design=design,\n          validation=\"Mfold\",folds=3L,nrepeat=2L,measure=\"BER\",\n          dist=\"max.dist\",progressBar=FALSE,seed=as.integer(seeds[index])\n        )\n        if(!is.null(trained$choice.keepX)) {\n          keep <- lapply(names(split$train),function(name)\n            as.integer(trained$choice.keepX[[name]][1]))\n          names(keep) <- names(split$train)\n        } else stop(\"Training-only DIABLO tuning did not return a keepX choice.\")\n      }\n    }\n    keep <- lapply(keep,function(k)rep(as.integer(k[1]),ncomp))\n    set.seed(as.integer(seeds[index]))\n    model <- mixOmics::block.splsda(\n      X=split$train,Y=split$y_train,ncomp=ncomp,\n      keepX=keep,design=design,scale=FALSE\n    )\n    selections[[index]] <- lapply(names(split$train),function(view)\n      selected_diablo_features(model,view,colnames(split$train[[view]])))\n    names(selections[[index]]) <- names(split$train)\n    predicted <- predict(model,newdata=split$test,dist=\"max.dist\")\n    vote <- predicted$WeightedVote[[\"max.dist\"]]\n    if(is.null(vote) || nrow(as.matrix(vote))!=length(split$testIds))\n      stop(\"DIABLO weighted vote missing or wrong holdout subject count.\")\n    classes <- as.character(as.matrix(vote)[,ncomp])\n    if(length(classes)!=length(split$testIds) ||\n       anyNA(classes)||any(!classes%in%levels(split$y_test)))\n      stop(\"Invalid/ambiguous DIABLO holdout predictions, no silent omissions.\")\n    actual <- as.character(split$y_test)\n    counts <- table(split$y_test)\n    recall <- vapply(levels(split$y_test),function(label)\n      mean(classes[actual==label]==label),numeric(1))\n    ber <- mean(1-recall)\n    all_rows[[index]] <- data.frame(\n      seed=seeds[index],sampleId=split$testIds,\n      actual=actual,predicted=classes,correct=as.integer(actual==classes),\n      stringsAsFactors=FALSE\n    )\n    summaries[[index]] <- list(seed=seeds[index],\n      trainingSubjects=length(split$trainIds),\n      heldOutSubjects=length(split$testIds),\n      balancedErrorRate=ber,\n      accuracy=mean(actual==classes),\n      classRecall=as.list(recall),\n      trainingOnlyTuning=isTRUE(tune))\n  }\n  predictions <- do.call(rbind,all_rows)\n  if(nrow(predictions)!=sum(vapply(summaries,function(x)x$heldOutSubjects,integer(1))))\n    stop(\"DIABLO holdout missing predictions.\")\n  stability <- diablo_selection_stability(selections)\n  dir.create(output_dir,recursive=TRUE,showWarnings=FALSE)\n  utils::write.csv(predictions,file.path(output_dir,\"diablo_outer_holdout.csv\"),row.names=FALSE)\n  saveRDS(list(versions=\"internal-fold-feature-selections-v1\",\n      selectedBySplit=selections,stability=stability),\n      file.path(output_dir,\"diablo_signature_stability.rds\"))\n  list(status=\"ok\",summary=list(\n    signatureStability=stability,\n    signatureStatus=\"internal_repeatability_only_not_validated_biomarker\",\n    evaluation=\"Repeated subject-level heldout, with training-only filtering/imputation/scaling and training-only keepX tuning\",\n    seeds=as.integer(seeds),folds=summaries,\n    meanBER=mean(vapply(summaries,function(x)x$balancedErrorRate,numeric(1))),\n    maxBER=max(vapply(summaries,function(x)x$balancedErrorRate,numeric(1))),\n    trainingPipeline=\"as-supplied log-scale omics, no varying batch or nuisance covariates; observed samples must be truly independent\",\n    caveat=\"Held-out subsets reuse the same source cohort across splits: not external replication. Outcome-related pre-import processing, MS global QC and study selection remain outside this validation.\"\n  ),predictions=predictions)\n}\n\nrun_diablo_blocks <- function(\n  blocks,\n  outcome,\n  output_dir,\n  ncomp = 2L,\n  keepX = NULL,\n  seed = 20260924L,\n  tune = TRUE,\n  nrepeat = 5L,\n  folds = NULL\n) {\n  require_namespace(\"mixOmics\")\n  blocks <- validate_blocks(blocks, min_samples = 6L)\n  blocks <- lapply(blocks, filter_informative_features)\n  if (any(vapply(blocks, ncol, integer(1)) < 2L)) {\n    stop(\"DIABLO requires at least two informative features in every block.\", call. = FALSE)\n  }\n\n  common <- rownames(blocks[[1]])\n  if (is.null(names(outcome))) {\n    if (length(outcome) != length(common)) stop(\"Unnamed outcome must have one value per shared sample.\", call. = FALSE)\n    y <- outcome\n  } else {\n    y <- outcome[common]\n  }\n  if (any(is.na(y)) || any(!nzchar(as.character(y)))) {\n    stop(\"Outcome contains missing values for shared samples.\", call. = FALSE)\n  }\n  y <- droplevels(factor(y))\n  if (nlevels(y) < 2L) stop(\"DIABLO requires at least two outcome classes.\", call. = FALSE)\n  class_counts <- table(y)\n  min_class <- min(class_counts)\n  if (min_class < 3L) {\n    stop(\"DIABLO tuning requires at least three samples in every class; use an exploratory non-supervised route instead.\", call. = FALSE)\n  }\n\n  if (is.null(folds)) folds <- min(5L, as.integer(min_class))\n  folds <- as.integer(max(3L, min(folds, min_class)))\n  # The automatic backend previously requested three repeats. Enforce at least\n  # five here so both direct calls and browser-triggered runs receive a more\n  # stable repeated-CV diagnostic without relying on the caller.\n  nrepeat <- as.integer(max(5L, nrepeat))\n  max_components <- max(1L, min(3L, nlevels(y), length(y) - 2L))\n  requested_components <- as.integer(max(1L, min(ncomp, max_components)))\n\n  design <- matrix(\n    0.1,\n    nrow = length(blocks),\n    ncol = length(blocks),\n    dimnames = list(names(blocks), names(blocks))\n  )\n  diag(design) <- 0\n\n  set.seed(seed)\n  tuning <- NULL\n  tuning_error <- NULL\n  tuned <- FALSE\n  final_ncomp <- requested_components\n  final_keepX <- normalise_keepx(keepX, blocks, final_ncomp)\n  test_keepX <- NULL\n\n  if (isTRUE(tune) && is.null(keepX)) {\n    test_keepX <- lapply(blocks, function(x) make_keepx_grid(ncol(x)))\n    if (all(vapply(test_keepX, length, integer(1)) >= 2L)) {\n      tuning <- try(\n        mixOmics::tune.block.splsda(\n          X = blocks,\n          Y = y,\n          ncomp = max_components,\n          test.keepX = test_keepX,\n          validation = \"Mfold\",\n          folds = folds,\n          dist = \"max.dist\",\n          measure = \"BER\",\n          nrepeat = nrepeat,\n          design = design,\n          progressBar = FALSE,\n          seed = as.integer(seed)\n        ),\n        silent = TRUE\n      )\n      if (!inherits(tuning, \"try-error\")) {\n        tuned_ncomp <- suppressWarnings(as.integer(tuning$choice.ncomp$ncomp))\n        if (length(tuned_ncomp) && is.finite(tuned_ncomp) && tuned_ncomp >= 1L) {\n          final_ncomp <- min(tuned_ncomp, max_components)\n        }\n        if (!is.null(tuning$choice.keepX)) {\n          final_keepX <- normalise_keepx(tuning$choice.keepX, blocks, final_ncomp)\n          tuned <- TRUE\n        }\n      } else {\n        tuning_error <- as.character(tuning)\n      }\n    } else {\n      tuning_error <- \"Automatic sparsity tuning was not attempted because at least one block had fewer than two admissible keepX candidates.\"\n    }\n  }\n\n  fit <- mixOmics::block.splsda(\n    X = blocks,\n    Y = y,\n    ncomp = final_ncomp,\n    keepX = final_keepX,\n    design = design\n  )\n\n  performance_seed <- as.integer(seed) + 1L\n  performance <- try(\n    mixOmics::perf(\n      fit,\n      validation = \"Mfold\",\n      folds = folds,\n      nrepeat = nrepeat,\n      progressBar = FALSE,\n      seed = performance_seed\n    ),\n    silent = TRUE\n  )\n  performance_error <- if (inherits(performance, \"try-error\")) as.character(performance) else NULL\n\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  saveRDS(fit, file.path(output_dir, \"diablo_model.rds\"))\n  if (!is.null(tuning) && !inherits(tuning, \"try-error\")) saveRDS(tuning, file.path(output_dir, \"diablo_tuning.rds\"))\n  if (!inherits(performance, \"try-error\")) saveRDS(performance, file.path(output_dir, \"diablo_performance.rds\"))\n\n  variates <- do.call(cbind, lapply(names(fit$variates), function(view) {\n    x <- fit$variates[[view]]\n    colnames(x) <- paste0(view, \"_comp\", seq_len(ncol(x)))\n    x\n  }))\n  write_matrix_csv(variates, file.path(output_dir, \"diablo_variates.csv\"))\n\n  selected <- lapply(names(blocks), function(view) {\n    lapply(seq_len(final_ncomp), function(comp) mixOmics::selectVar(fit, block = view, comp = comp)$value)\n  })\n  names(selected) <- names(blocks)\n  saveRDS(selected, file.path(output_dir, \"diablo_selected_variables.rds\"))\n\n  summary <- list(\n    method = \"mixOmics DIABLO / block.splsda\",\n    seed = as.integer(seed),\n    performance_seed = performance_seed,\n    samples = length(y),\n    classes = as.list(class_counts),\n    blocks = vapply(blocks, ncol, integer(1)),\n    tuning = list(\n      requested = isTRUE(tune),\n      completed = tuned,\n      validation = \"repeated M-fold CV; folds bounded by the smallest class\",\n      folds = folds,\n      repeats = nrepeat,\n      measure = \"BER\",\n      candidate_keepX = test_keepX,\n      ncomp = final_ncomp,\n      keepX = final_keepX,\n      error = tuning_error,\n      note = if (tuned) \"Final model uses repeated cross-validated sparsity choices.\" else \"Automatic tuning was unavailable; conservative keepX values were used and this model should be treated as exploratory.\"\n    ),\n    internal_performance = safe_perf_summary(performance),\n    internal_performance_error = performance_error,\n    validation_boundary = \"Hyperparameter tuning and the reported perf() diagnostic use the same cohort. Repeated CV reduces split sensitivity but does not create an independent validation cohort; external validation remains required for generalisable biomarker or prediction claims.\",\n    interpretation = \"Selected variables are a supervised multivariate signature. Their stability and external validity must be assessed before biomarker claims.\"\n  )\n  saveRDS(summary, file.path(output_dir, \"diablo_summary.rds\"))\n  invisible(list(model = fit, summary = summary, tuning = tuning, performance = performance))\n}\n\n# Narrow R1 *eligibility* preflight: two independent groups, an additive\n# full-rank design and raw nonnegative integer counts. This intentionally\n# DOES NOT certify data provenance, statistical power, differential expression,\n# false-discovery control or any biological conclusion. No silent sample\n# intersection, pseudoreplication or feature-ID repair in this path.\nrnaseq_confirmatory_preflight <- function(counts, metadata, design_formula,\n                                          contrast,\n                                          min_subjects_per_group=3L) {\n  if(!is.matrix(counts)||!is.numeric(counts)||\n     nrow(counts)<6L||ncol(counts)<20L||\n     is.null(rownames(counts))||is.null(colnames(counts))||\n     anyNA(rownames(counts))||anyNA(colnames(counts))||\n     any(!nzchar(rownames(counts)))||any(!nzchar(colnames(counts)))||\n     anyDuplicated(rownames(counts))||anyDuplicated(colnames(counts)))\n    stop(\"R1 RNA-seq requires >=6 biological samples, >=20 features and unique nonempty input IDs\")\n  if(any(!is.finite(counts))||any(counts<0)||\n     any(abs(counts-round(counts))>1e-8)||any(rowSums(counts)<=0))\n    stop(\"R1 RNA-seq requires finite, non-negative, unnormalised integer counts and nonempty sample libraries\")\n  if(!is.data.frame(metadata)||is.null(rownames(metadata))||\n     anyNA(rownames(metadata))||anyDuplicated(rownames(metadata))||\n     any(!nzchar(rownames(metadata)))||\n     !setequal(rownames(metadata),rownames(counts))||\n     nrow(metadata)!=nrow(counts))\n    stop(\"R1 RNA-seq sample IDs must match metadata exactly; never drop or multiply biological samples\")\n  if(!all(c(\"subject_id\",\"condition\")%in%names(metadata))||\n     anyNA(metadata$subject_id)||any(!nzchar(trimws(as.character(metadata$subject_id))))||\n     anyDuplicated(as.character(metadata$subject_id)))\n    stop(\"R1 RNA-seq needs one unique, known biological subject per sample (no pseudoreplicates)\")\n  if(!inherits(design_formula,\"formula\")||\n     length(design_formula)!=2L||\n     attr(stats::terms(design_formula),\"intercept\")!=1L||\n     any(attr(stats::terms(design_formula),\"order\")!=1L))\n    stop(\"R1 RNA-seq only supports an additive formula with an intercept (no interactions, pairing or offsets)\")\n  fields<-all.vars(design_formula)\n  labels<-attr(stats::terms(design_formula),\"term.labels\")\n  if(!length(labels)||any(!grepl(\"^[A-Za-z][A-Za-z0-9_.]*$\",labels))||\n     !\"condition\"%in%labels||anyDuplicated(labels)||\n     any(!fields%in%names(metadata)))\n    stop(\"R1 RNA-seq needs a named condition main effect and plain additive measured covariates\")\n  m<-metadata[match(rownames(counts),rownames(metadata)),,drop=FALSE]\n  for(field in fields){\n    value<-as.character(m[[field]])\n    if(anyNA(value)||any(!nzchar(trimws(value))))\n      stop(paste(\"R1 RNA-seq has missing or blank design covariate:\",field))\n  }\n  groups<-unique(as.character(m$condition))\n  if(length(groups)!=2L||any(!nzchar(groups)))\n    stop(\"R1 RNA-seq requires exactly two nonempty independent conditions\")\n  n_by_group<-table(as.character(m$condition))\n  if(length(min_subjects_per_group)!=1L||!is.finite(min_subjects_per_group)||\n     min_subjects_per_group!=as.integer(min_subjects_per_group)||\n     min_subjects_per_group<3L||\n     any(n_by_group<min_subjects_per_group))\n    stop(\"R1 RNA-seq has too few independent biological subjects per group (minimum 3, not a power claim)\")\n  if(!is.character(contrast)||length(contrast)!=3L||\n     !identical(contrast[[1L]],\"condition\")||\n     identical(contrast[[2L]],contrast[[3L]])||\n     !setequal(contrast[2:3],groups))\n    stop(\"R1 RNA-seq requires one explicit two-level condition contrast, not an implicit coefficient\")\n  batch<-if(\"batch\"%in%names(m))trimws(as.character(m$batch)) else character()\n  observed_batch<-unique(batch[!is.na(batch)&nzchar(batch)])\n  if(length(observed_batch)>1L && !\"batch\"%in%labels)\n    stop(\"R1 RNA-seq detects varying known batches excluded from the additive design\")\n  if(\"batch\"%in%labels && (anyNA(batch)||any(!nzchar(batch))))\n    stop(\"R1 RNA-seq cannot adjust a partially missing technical batch\")\n  if(\"condition\"%in%labels && !\"condition\"%in%names(m))\n    stop(\"Missing condition in confirmatory design\")\n  for(field in fields) {\n    if(is.character(m[[field]]))m[[field]]<-factor(m[[field]])\n  }\n  matrix_design<-tryCatch(stats::model.matrix(design_formula,data=m,\n                                               na.action=stats::na.fail),\n                          error=function(e)stop(\"R1 RNA-seq design cannot be constructed: \",conditionMessage(e)))\n  if(nrow(matrix_design)!=nrow(counts)||qr(matrix_design)$rank!=ncol(matrix_design)||\n     nrow(matrix_design)-ncol(matrix_design)<2L)\n    stop(\"R1 RNA-seq design is non-identifiable or has insufficient residual degrees of freedom\")\n  list(\n    status=\"eligible_for_reference_fitting_only\",\n    cohort_samples=nrow(counts),measured_features=ncol(counts),\n    independent_subjects=length(unique(m$subject_id)),\n    group_sizes=as.list(n_by_group),\n    rank=qr(matrix_design)$rank,model_columns=ncol(matrix_design),\n    residual_df=nrow(matrix_design)-ncol(matrix_design),\n    condition_contrast=unname(contrast),covariates=labels[labels!=\"condition\"],\n    missing_or_unverified_batch=length(observed_batch)==0L,\n    rejected_silent_subject_loss=TRUE,\n    certified=FALSE,\n    limitations=c(\n      \"Integer-looking input is not proof of genuine raw sequencer counts.\",\n      \"At least three subjects per group is a software guard, NOT a statistical power guarantee.\",\n      \"Batch measurement, library and mapping QC, biological independence, protocol preregistration, multiple-testing family and external scientific review remain necessary.\",\n      \"Passing preflight is not confirmatory inference, independent replication or clinical certification.\"\n    )\n  )\n}\n\nrun_deseq2_counts <- function(\n  counts,\n  metadata,\n  output_dir,\n  design_formula = ~ condition,\n  contrast = NULL,\n  alpha = 0.05,\n  confirmatory_contract = FALSE\n) {\n  input_contract <- if(isTRUE(confirmatory_contract))\n    rnaseq_confirmatory_preflight(as.matrix(counts), as.data.frame(metadata),\n                                 design_formula, contrast)\n    else NULL\n  require_namespace(\"DESeq2\")\n  counts <- as.matrix(counts)\n  storage.mode(counts) <- \"numeric\"\n  if (is.null(rownames(counts))) stop(\"counts must use sample IDs as row names.\", call. = FALSE)\n  metadata <- as.data.frame(metadata)\n  if (is.null(rownames(metadata))) stop(\"metadata must use sample IDs as row names.\", call. = FALSE)\n  common <- intersect(rownames(counts), rownames(metadata))\n  if (length(common) < 3L) stop(\"At least three matched samples are required.\", call. = FALSE)\n  counts <- counts[common, , drop = FALSE]\n  metadata <- metadata[common, , drop = FALSE]\n  if (any(!is.finite(counts)) || any(counts < 0) ||\n      any(abs(counts - round(counts)) > 1e-8)) {\n    stop(\"DESeq2 requires non-negative, finite, unnormalised integer counts. Do not silently round normalised or fractional abundances.\", call. = FALSE)\n  }\n  design <- stats::model.matrix(design_formula, data=metadata)\n  if (qr(design)$rank < ncol(design)) stop(\"DESeq2 design is rank-deficient.\", call. = FALSE)\n\n  dds <- DESeq2::DESeqDataSetFromMatrix(\n    countData = t(counts),\n    colData = metadata,\n    design = design_formula\n  )\n  keep <- rowSums(DESeq2::counts(dds) >= 10) >= max(2L, ceiling(ncol(dds) * 0.2))\n  if (!any(keep)) stop(\"Expression filtering removed all genes.\", call. = FALSE)\n  dds <- dds[keep, ]\n  dds <- DESeq2::DESeq(dds, quiet = TRUE)\n\n  res <- if (is.null(contrast)) {\n    DESeq2::results(dds, alpha = alpha)\n  } else {\n    DESeq2::results(dds, contrast = contrast, alpha = alpha)\n  }\n  result <- data.frame(feature = rownames(res), as.data.frame(res), row.names = NULL, check.names = FALSE)\n\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  utils::write.csv(result, file.path(output_dir, \"deseq2_results.csv\"), row.names = FALSE)\n  saveRDS(dds, file.path(output_dir, \"deseq2_model.rds\"))\n  invisible(list(model = dds, results = result,\n                 confirmatory_input_contract = input_contract))\n}\n\nrun_edger_ql_counts <- function(\n  counts,\n  metadata,\n  output_dir,\n  design_formula = ~ condition,\n  coefficient = NULL,\n  robust = TRUE\n) {\n  require_namespace(\"edgeR\")\n  counts <- as.matrix(counts)\n  storage.mode(counts) <- \"numeric\"\n  metadata <- as.data.frame(metadata)\n  if (is.null(rownames(counts)) || is.null(rownames(metadata))) {\n    stop(\"counts and metadata must use sample IDs as row names.\", call. = FALSE)\n  }\n  common <- intersect(rownames(counts), rownames(metadata))\n  if (length(common) < 3L) stop(\"At least three matched samples are required.\", call. = FALSE)\n  x <- counts[common, , drop = FALSE]\n  meta <- metadata[common, , drop = FALSE]\n  design <- stats::model.matrix(design_formula, data = meta)\n  if (qr(design)$rank < ncol(design)) stop(\"The edgeR design matrix is rank-deficient.\", call. = FALSE)\n\n  if (any(!is.finite(x)) || any(x < 0)) {\n    stop(\"RNA-seq counts must be finite and non-negative.\", call. = FALSE)\n  }\n  # edgeR and voom can process estimated fractional counts directly; never\n  # silently round them as that modifies the input and its mean/variance.\n  y <- edgeR::DGEList(counts = t(x))\n  keep <- edgeR::filterByExpr(y, design = design)\n  if (!any(keep)) stop(\"edgeR::filterByExpr removed all genes.\", call. = FALSE)\n  y <- y[keep, , keep.lib.sizes = FALSE]\n  y <- edgeR::calcNormFactors(y, method = \"TMM\")\n  y <- edgeR::estimateDisp(y, design = design, robust = robust)\n  fit <- edgeR::glmQLFit(y, design = design, robust = robust)\n  if (is.null(coefficient)) coefficient <- ncol(design)\n  test <- edgeR::glmQLFTest(fit, coef = coefficient)\n  table <- edgeR::topTags(test, n = Inf, sort.by = \"PValue\")$table\n  result <- data.frame(feature = rownames(table), table, row.names = NULL, check.names = FALSE)\n\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  utils::write.csv(result, file.path(output_dir, \"edger_ql_results.csv\"), row.names = FALSE)\n  saveRDS(list(dge = y, fit = fit, test = test, design = design), file.path(output_dir, \"edger_ql_model.rds\"))\n  invisible(list(model = fit, test = test, results = result, design = design, dge = y))\n}\n\nrun_voom_counts <- function(\n  counts,\n  metadata,\n  output_dir,\n  design_formula = ~ condition,\n  coefficient = NULL,\n  robust = TRUE,\n  trend = FALSE\n) {\n  require_namespace(\"edgeR\")\n  require_namespace(\"limma\")\n  counts <- as.matrix(counts)\n  storage.mode(counts) <- \"numeric\"\n  metadata <- as.data.frame(metadata)\n  if (is.null(rownames(counts)) || is.null(rownames(metadata))) {\n    stop(\"counts and metadata must use sample IDs as row names.\", call. = FALSE)\n  }\n  common <- intersect(rownames(counts), rownames(metadata))\n  if (length(common) < 3L) stop(\"At least three matched samples are required.\", call. = FALSE)\n  x <- counts[common, , drop = FALSE]\n  meta <- metadata[common, , drop = FALSE]\n  design <- stats::model.matrix(design_formula, data = meta)\n  if (qr(design)$rank < ncol(design)) stop(\"The voom design matrix is rank-deficient.\", call. = FALSE)\n\n  if (any(!is.finite(x)) || any(x < 0)) {\n    stop(\"RNA-seq counts must be finite and non-negative.\", call. = FALSE)\n  }\n  # edgeR and voom can process estimated fractional counts directly; never\n  # silently round them as that modifies the input and its mean/variance.\n  y <- edgeR::DGEList(counts = t(x))\n  keep <- edgeR::filterByExpr(y, design = design)\n  if (!any(keep)) stop(\"edgeR::filterByExpr removed all genes.\", call. = FALSE)\n  y <- y[keep, , keep.lib.sizes = FALSE]\n  y <- edgeR::calcNormFactors(y, method = \"TMM\")\n  voom <- limma::voom(y, design = design, plot = FALSE)\n  fit <- limma::lmFit(voom, design)\n  fit <- limma::eBayes(fit, robust = robust, trend = trend)\n  if (is.null(coefficient)) coefficient <- ncol(design)\n  result <- limma::topTable(fit, coef = coefficient, number = Inf, sort.by = \"P\")\n  result <- data.frame(feature = rownames(result), result, row.names = NULL, check.names = FALSE)\n\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  utils::write.csv(result, file.path(output_dir, \"voom_results.csv\"), row.names = FALSE)\n  utils::write.csv(data.frame(feature = rownames(voom$E), voom$E, check.names = FALSE), file.path(output_dir, \"voom_logcpm.csv\"), row.names = FALSE)\n  saveRDS(list(dge = y, voom = voom, fit = fit, design = design), file.path(output_dir, \"voom_model.rds\"))\n  invisible(list(model = fit, results = result, design = design, voom = voom, dge = y))\n}\n\ncompare_rnaseq_methods <- function(deseq_results, voom_results, alpha = 0.05) {\n  a <- as.data.frame(deseq_results, stringsAsFactors = FALSE)\n  b <- as.data.frame(voom_results, stringsAsFactors = FALSE)\n  if (!all(c(\"feature\", \"stat\", \"padj\") %in% names(a)) ||\n      !all(c(\"feature\", \"t\", \"adj.P.Val\") %in% names(b))) {\n    return(list(status = \"unavailable\", message = \"Required DESeq2/voom result columns were not available.\"))\n  }\n  merged <- merge(\n    a[, c(\"feature\", \"stat\", \"padj\")],\n    b[, c(\"feature\", \"t\", \"adj.P.Val\")],\n    by = \"feature\",\n    all = FALSE\n  )\n  names(merged) <- c(\"feature\", \"deseq2_stat\", \"deseq2_q\", \"voom_t\", \"voom_q\")\n  valid <- is.finite(merged$deseq2_stat) & is.finite(merged$voom_t)\n  rho <- if (sum(valid) >= 3L) suppressWarnings(stats::cor(merged$deseq2_stat[valid], merged$voom_t[valid], method = \"spearman\")) else NA_real_\n  sig_a <- is.finite(merged$deseq2_q) & merged$deseq2_q <= alpha\n  sig_b <- is.finite(merged$voom_q) & merged$voom_q <= alpha\n  union_sig <- sig_a | sig_b\n  sign_agreement <- if (any(union_sig)) mean(sign(merged$deseq2_stat[union_sig]) == sign(merged$voom_t[union_sig]), na.rm = TRUE) else NA_real_\n  overlap <- sum(sig_a & sig_b)\n  union_n <- sum(union_sig)\n  jaccard <- if (union_n > 0L) overlap / union_n else NA_real_\n  list(\n    status = \"ok\",\n    common_features = nrow(merged),\n    spearman_statistics = unname(rho),\n    deseq2_significant = sum(sig_a),\n    voom_significant = sum(sig_b),\n    significant_overlap = overlap,\n    significant_jaccard = jaccard,\n    sign_agreement_among_any_significant = sign_agreement,\n    alpha = alpha,\n    interpretation = \"Concordance is a sensitivity analysis. q-values from distinct methods are not averaged or combined.\"\n  )\n}\n\nrun_limma_matrix <- function(\n  matrix,\n  metadata,\n  output_dir,\n  design_formula = ~ condition,\n  coefficient = NULL,\n  trend = TRUE,\n  robust = TRUE\n) {\n  require_namespace(\"limma\")\n  matrix <- as.matrix(matrix)\n  storage.mode(matrix) <- \"double\"\n  metadata <- as.data.frame(metadata)\n  if (is.null(rownames(matrix)) || is.null(rownames(metadata))) {\n    stop(\"matrix and metadata must use sample IDs as row names.\", call. = FALSE)\n  }\n  common <- intersect(rownames(matrix), rownames(metadata))\n  if (length(common) < 3L) stop(\"At least three matched samples are required.\", call. = FALSE)\n  x <- matrix[common, , drop = FALSE]\n  meta <- metadata[common, , drop = FALSE]\n  design <- stats::model.matrix(design_formula, data = meta)\n  if (qr(design)$rank < ncol(design)) stop(\"The limma design matrix is rank-deficient.\", call. = FALSE)\n\n  fit <- limma::lmFit(t(x), design)\n  fit <- limma::eBayes(fit, trend = trend, robust = robust)\n  if (is.null(coefficient)) coefficient <- ncol(design)\n  result <- limma::topTable(fit, coef = coefficient, number = Inf, sort.by = \"P\")\n  result <- data.frame(feature = rownames(result), result, row.names = NULL, check.names = FALSE)\n\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  utils::write.csv(result, file.path(output_dir, \"limma_results.csv\"), row.names = FALSE)\n  saveRDS(fit, file.path(output_dir, \"limma_model.rds\"))\n  invisible(list(model = fit, results = result, design = design))\n}\n\n# Strict time units: numeric and Tn/Dn/Wn only. A mixed unit or labels like\n# baseline/followup cannot be converted deterministically into a rate.\nparse_longitudinal_time <- function(timepoint) {\n  raw <- trimws(as.character(timepoint))\n  if (anyNA(raw) || any(!nzchar(raw))) stop(\"Longitudinal timepoint is missing.\")\n  kind <- ifelse(grepl(\"^[+]?[0-9]+([.][0-9]+)?$\",raw),\"numeric\",\n    ifelse(grepl(\"^[Tt][+]?[0-9]+([.][0-9]+)?$\",raw),\"T\",\n      ifelse(grepl(\"^[Dd][+]?[0-9]+([.][0-9]+)?$\",raw),\"D\",\n        ifelse(grepl(\"^[Ww][+]?[0-9]+([.][0-9]+)?$\",raw),\"W\",\"invalid\"))))\n  if (any(kind==\"invalid\") || length(unique(kind))!=1L)\n    stop(\"Longitudinal timepoint must use one consistent numeric or Tn/Dn/Wn scale (e.g. T0,T1,T2); no mixed units or ambiguous visit names.\")\n  values <- suppressWarnings(as.numeric(if(kind[1]==\"numeric\")raw else substring(raw,2L)))\n  if(any(!is.finite(values)))stop(\"Unparseable longitudinal timepoint.\")\n  list(time=values,timeScale=kind[1])\n}\n\nvalidate_longitudinal_reference_design <- function(meta,subject_column=\"subject_id\") {\n  if(!subject_column%in%names(meta)||!\"condition\"%in%names(meta)||!\"time\"%in%names(meta))\n    stop(\"Longitudinal design needs subject_id, condition and numeric time.\")\n  ids <- as.character(meta[[subject_column]])\n  conditions <- as.character(meta$condition)\n  if (anyNA(ids)||any(!nzchar(ids))||anyNA(conditions)||any(!nzchar(conditions)))\n    stop(\"Longitudinal subject_id/condition cannot be missing.\")\n  if(any(!is.finite(meta$time)))stop(\"Longitudinal time contains non-finite entries.\")\n  if(anyDuplicated(paste(ids,format(meta$time,digits=14),sep=\"\\r\")))\n    stop(\"Duplicated subject-time observation. Aggregate technical replicates first; do not count technical measurements as biological subjects.\")\n  subject_conditions <- split(conditions,ids)\n  if(any(lengths(lapply(subject_conditions,unique)) != 1L))\n    stop(\"Condition changes within subjects: use a crossover/time-dependent design, not fixed-group longitudinal lmer.\")\n  by_subject <- split(meta$time,ids)\n  if(length(by_subject)<10L || any(lengths(lapply(by_subject,unique))<2L))\n    stop(\"Longitudinal reference requires >=10 independent subjects and >=2 observed distinct times for every subject; sparse subjects need a prespecified missing-visits model.\")\n  groups <- sort(unique(conditions))\n  if(length(groups)!=2L)stop(\"This reference longitudinal contrast requires exactly two fixed treatment groups.\")\n  subjects_per_group <- table(vapply(subject_conditions,function(x)x[1],character(1)))\n  if(any(subjects_per_group<5L))\n    stop(\"Longitudinal reference needs at least 5 independent subjects per group.\")\n  for(group in groups)if(length(unique(meta$time[conditions==group]))<2L)\n    stop(\"Each group needs at least two distinct time points.\")\n  list(nSubjects=length(by_subject),nObservations=nrow(meta),\n       subjectsPerGroup=as.list(subjects_per_group),\n       contrast=paste0(\"condition\",groups[2],\":time\"),\n       groups=groups,\n       note=\"Longitudinal time slope assumes linear effect and stable group membership; checked eligibility does not certify MAR censoring, residual assumptions or adequate power.\")\n}\n\nsubject_has_repeated_time <- function(meta, subject_column = \"subject_id\", time_column = \"time\") {\n  if (!all(c(subject_column,time_column)%in%names(meta)))return(FALSE)\n  counts <- tapply(meta[[time_column]],meta[[subject_column]],\n    function(x)length(unique(x[is.finite(x)])))\n  counts <- counts[is.finite(counts)]\n  length(counts)>=10L && sum(counts>=3L)>=10L\n}\n\nrun_lmer_matrix <- function(\n  matrix,\n  metadata,\n  output_dir,\n  fixed_formula = \"condition * time\",\n  subject_column = \"subject_id\",\n  interaction_term = NULL,\n  random_slope = \"auto\"\n) {\n  require_namespace(\"lmerTest\")\n  require_namespace(\"lme4\")\n  matrix <- as.matrix(matrix)\n  storage.mode(matrix) <- \"double\"\n  metadata <- as.data.frame(metadata)\n  if(is.null(rownames(matrix))||is.null(rownames(metadata)))\n    stop(\"Longitudinal sample identifiers must be explicit matrix and metadata row names.\")\n  if(anyDuplicated(rownames(matrix))||anyDuplicated(rownames(metadata)))\n    stop(\"Longitudinal sample identifiers must be unique after technical replicate aggregation.\")\n  common <- intersect(rownames(matrix),rownames(metadata))\n  if(length(common)<20L)stop(\"At least 20 matched longitudinal observations are needed.\")\n  x <- matrix[common,,drop=FALSE]\n  meta <- metadata[common,,drop=FALSE]\n  if(!\"time\"%in%names(meta)||!\"condition\"%in%names(meta))\n    stop(\"Missing numeric time or group for explicit longitudinal contrast.\")\n  meta$time <- as.numeric(meta$time)\n  design <- validate_longitudinal_reference_design(meta,subject_column)\n  meta$condition <- factor(as.character(meta$condition),levels=design$groups)\n  expected_term <- design$contrast\n  if(!is.null(interaction_term) && !identical(interaction_term,expected_term))\n    stop(paste(\"Invalid longitudinal contrast; expected\",expected_term))\n  if(!grepl(\"condition[[:space:]]*\\\\*[[:space:]]*time\",fixed_formula))\n    stop(\"Longitudinal reference requires an explicit condition-by-time interaction.\")\n  fixed <- stats::as.formula(paste0(\"~\",fixed_formula))\n  if(anyNA(stats::model.frame(fixed,data=meta,na.action=stats::na.pass)))\n    stop(\"Missing covariates in a longitudinal model. Resolve before fitting.\")\n  design_matrix <- stats::model.matrix(fixed,data=meta)\n  if(qr(design_matrix)$rank<ncol(design_matrix) ||\n      !(expected_term%in%colnames(design_matrix)))\n    stop(\"Aliased longitudinal fixed effects or missing explicit condition-by-time coefficient.\")\n  try_slope <- identical(random_slope,TRUE)||identical(random_slope,\"yes\")||\n    (identical(random_slope,\"auto\") && subject_has_repeated_time(meta,subject_column,\"time\"))\n  intercept_formula <- stats::as.formula(paste0(\"value ~ \",fixed_formula,\" + (1|\",subject_column,\")\"))\n  slope_formula <- stats::as.formula(paste0(\"value ~ \",fixed_formula,\" + (1 + time|\",subject_column,\")\"))\n  results <- vector(\"list\",ncol(x))\n  for(j in seq_len(ncol(x))) {\n    feature <- colnames(x)[j]\n    if(is.null(feature)||!nzchar(feature)) feature <- paste0(\"F\",j)\n    dat <- meta\n    dat$value <- x[,j]\n    dat <- dat[is.finite(dat$value),,drop=FALSE]\n    row <- data.frame(\n      feature=feature,term=expected_term,estimate=NA_real_,\n      std_error=NA_real_,df=NA_real_,statistic=NA_real_,\n      p_value=NA_real_,q_bh=NA_real_,\n      n_observations=nrow(dat),\n      n_subjects=length(unique(dat[[subject_column]])),\n      random_effect_structure=NA_character_,\n      status=\"not_estimable\",stringsAsFactors=FALSE\n    )\n    if(nrow(dat)<20L) {row$status <- \"insufficient_observations\";results[[j]]<-row;next}\n    eligible <- try(validate_longitudinal_reference_design(dat,subject_column),silent=TRUE)\n    if(inherits(eligible,\"try-error\")) {\n      row$status <- \"incomplete_feature_specific_subject_visits\"\n      results[[j]]<-row;next\n    }\n    if(length(unique(dat$value))<3L||stats::sd(dat$value)<1e-10) {\n      row$status <- \"constant_feature\";results[[j]]<-row;next\n    }\n    fd <- stats::model.matrix(fixed,data=dat)\n    if(qr(fd)$rank<ncol(fd)) {\n      row$status <- \"feature_specific_rank_deficient\"\n      results[[j]]<-row;next\n    }\n    fit <- NULL\n    used <- \"random_intercept\"\n    fallback <- FALSE\n    if(try_slope && subject_has_repeated_time(dat,subject_column,\"time\")) {\n      candidate <- try(suppressWarnings(lmerTest::lmer(\n        slope_formula,data=dat,REML=FALSE,\n        control=lme4::lmerControl(optimizer=\"bobyqa\"))),silent=TRUE)\n      if(!inherits(candidate,\"try-error\")&&!lme4::isSingular(candidate,tol=1e-4) &&\n          is.null(candidate@optinfo$conv$lme4$messages)) {\n        fit <- candidate;used <- \"random_intercept_and_slope\"\n      } else fallback <- TRUE\n    }\n    if(is.null(fit)) {\n      candidate <- try(suppressWarnings(lmerTest::lmer(\n        intercept_formula,data=dat,REML=FALSE,\n        control=lme4::lmerControl(optimizer=\"bobyqa\"))),silent=TRUE)\n      if(!inherits(candidate,\"try-error\")&&!lme4::isSingular(candidate,tol=1e-4) &&\n          is.null(candidate@optinfo$conv$lme4$messages))fit <- candidate\n    }\n    if(is.null(fit)) {\n      row$status <- \"singular_or_nonconvergent_fit\"\n      results[[j]]<-row;next\n    }\n    coefs <- summary(fit)$coefficients\n    if(!(expected_term%in%rownames(coefs)) ||\n        !all(c(\"Estimate\",\"Std. Error\",\"Pr(>|t|)\")%in%colnames(coefs))) {\n      row$status <- \"missing_explicit_interaction\"\n      results[[j]]<-row;next\n    }\n    xterm <- coefs[expected_term,,drop=FALSE]\n    beta <- unname(xterm[1,\"Estimate\"])\n    se <- unname(xterm[1,\"Std. Error\"])\n    p <- unname(xterm[1,\"Pr(>|t|)\"])\n    if(!all(is.finite(c(beta,se,p))) || se<=0 || p<0 || p>1) {\n      row$status <- \"invalid_inference\"\n      results[[j]]<-row;next\n    }\n    row$estimate <- beta\n    row$std_error <- se\n    row$df <- if(\"df\"%in%colnames(xterm))unname(xterm[1,\"df\"])else NA_real_\n    row$statistic <- unname(xterm[1,\"t value\"])\n    row$p_value <- p\n    row$random_effect_structure <- used\n    row$status <- if(fallback)\"ok_random_slope_fallback\" else \"ok\"\n    results[[j]] <- row\n  }\n  result <- do.call(rbind,results)\n  if(is.null(result))result <- data.frame()\n  if(nrow(result)) {\n    # BH denominator is the ORIGINAL supplied feature family: failures p=1.\n    complete_p <- ifelse(is.finite(result$p_value),result$p_value,1)\n    all_q <- stats::p.adjust(complete_p,method=\"BH\")\n    result$q_bh <- ifelse(is.finite(result$p_value),all_q,NA_real_)\n  }\n  dir.create(output_dir,recursive=TRUE,showWarnings=FALSE)\n  utils::write.csv(result,file.path(output_dir,\"lmer_results.csv\"),row.names=FALSE)\n  attr(result,\"design_summary\") <- c(design,\n    list(attemptedFeatures=ncol(x),\n         estimableFeatures=sum(is.finite(result$p_value)),\n         blockedFeatures=sum(!is.finite(result$p_value)),\n         randomSlopeFallbacks=sum(result$status==\"ok_random_slope_fallback\")))\n  result\n}\n\nrun_fgsea_ranked <- function(\n  ranks,\n  pathways,\n  output_dir,\n  min_size = 10L,\n  max_size = 500L,\n  seed = 20260924L\n) {\n  require_namespace(\"fgsea\")\n  if (is.null(names(ranks))) stop(\"ranks must be a named numeric vector.\", call. = FALSE)\n  ranks <- ranks[is.finite(ranks)]\n  ranks <- sort(ranks, decreasing = TRUE)\n  set.seed(seed)\n  result <- fgsea::fgsea(\n    pathways = pathways,\n    stats = ranks,\n    minSize = as.integer(min_size),\n    maxSize = as.integer(max_size)\n  )\n  result <- as.data.frame(result)\n  if (\"leadingEdge\" %in% names(result)) {\n    result$leadingEdge <- vapply(result$leadingEdge, paste, collapse = \";\", FUN.VALUE = character(1))\n  }\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  utils::write.csv(result, file.path(output_dir, \"fgsea_results.csv\"), row.names = FALSE)\n  invisible(result)\n}\n\n\n# Feature-wise R survival reference (not automated clinical confirmation).\n# Unit of analysis is the unique independent subject, never each omics assay.\n# This intentionally declines longitudinal/time-dependent and competing-risk\n# designs; such models require their own protocol and validation.\nrun_cox_survival_reference <- function(\n  matrix,\n  metadata,\n  output_dir,\n  covariates = character(),\n  ties = \"efron\",\n  min_events = 12L\n) {\n  require_namespace(\"survival\")\n  if (!identical(ties,\"efron\") && !identical(ties,\"breslow\"))\n    stop(\"Unsupported Cox ties policy.\")\n  x <- as.matrix(matrix)\n  storage.mode(x) <- \"double\"\n  if (is.null(rownames(x)) || !length(rownames(x)) || anyDuplicated(rownames(x)))\n    stop(\"Survival reference requires unique sample identifiers on each matrix row.\")\n  m <- metadata[match(rownames(x), metadata$sample_id),,drop=FALSE]\n  if (anyNA(m$sample_id) || anyNA(m$subject_id) ||\n      anyDuplicated(m$subject_id) || any(!nzchar(as.character(m$subject_id))))\n    stop(\"Survival reference requires exactly one observation per independent subject. Repeated visits need a time-dependent or clustered model.\")\n  if (nrow(x) < 20L)stop(\"Survival reference requires at least 20 independent subjects.\")\n  times <- suppressWarnings(as.numeric(m$survival_time))\n  events <- suppressWarnings(as.numeric(m$survival_event))\n  if (any(!is.finite(times) | times<=0) ||\n      any(!is.finite(events) | !events%in%c(0,1)))\n    stop(\"Complete, positive survival times and binary 0/1 event coding required; never silently omit or recode outcomes.\")\n  covariates <- unique(as.character(covariates))\n  if (any(!grepl(\"^[A-Za-z][A-Za-z0-9_]*$\",covariates)) ||\n      any(covariates%in%c(\"assay_feature\",\"survival_time\",\"survival_event\",\"subject_id\",\"sample_id\")))\n    stop(\"Invalid survival covariate identifier.\")\n  if (any(!covariates%in%names(m)))stop(\"Mapped survival covariate not present in sample metadata.\")\n  nuisance <- character()\n  if (\"batch\"%in%names(m)) {\n    batch_values <- as.character(m$batch)\n    batch_values[is.na(batch_values)] <- \"\"\n    if (length(unique(batch_values[nzchar(batch_values)])) > 1L) {\n      if(any(!nzchar(batch_values)))stop(\"Batch covariate has missing values; resolve before Cox reference.\")\n      m$batch <- factor(batch_values)\n      nuisance <- c(nuisance,\"batch\")\n    }\n  }\n  for (name in covariates) {\n    values <- m[[name]]\n    if (anyNA(values) || any(!nzchar(as.character(values))))\n      stop(paste(\"Missing values in survival covariate\",name))\n    numeric <- suppressWarnings(as.numeric(as.character(values)))\n    if(all(is.finite(numeric)))m[[name]] <- numeric\n    else m[[name]] <- factor(as.character(values))\n    if(length(unique(m[[name]]))>1L)nuisance <- c(nuisance,name)\n  }\n  min_events <- max(12L,as.integer(min_events))\n  min_events <- max(min_events,4L*(length(nuisance)+2L))\n  if (sum(events) < min_events)stop(\n    sprintf(\"Too few observed survival events for the declared model: %d; require >= %d. This is a conservative software guard, not a power guarantee.\",sum(events),min_events)\n  )\n  m$survival_time <- times\n  m$survival_event <- events\n  output <- vector(\"list\",ncol(x))\n  form <- stats::reformulate(c(\"assay_feature\",nuisance),\n    response=\"survival::Surv(survival_time, survival_event)\")\n  for (j in seq_len(ncol(x))) {\n    feature <- colnames(x)[j]\n    if (is.null(feature) || !nzchar(feature))feature <- paste0(\"F\",j)\n    observed <- is.finite(x[,j])\n    n_observed <- sum(observed)\n    n_events <- sum(events[observed])\n    result <- data.frame(\n      feature=feature,effect=NA_real_,standardError=NA_real_,\n      pValue=NA_real_,qValue=NA_real_,hazardRatio=NA_real_,\n      ciLow=NA_real_,ciHigh=NA_real_,\n      proportionalHazardsP=NA_real_,globalPhP=NA_real_,\n      nSubjects=n_observed,nEvents=n_events,\n      missingFraction=1-n_observed/nrow(x),\n      status=\"not_estimable\",stringsAsFactors=FALSE\n    )\n    if (n_observed < 20L || n_events < min_events) {\n      result$status <- \"insufficient_observations_or_events\"\n      output[[j]] <- result\n      next\n    }\n    data <- m[observed,,drop=FALSE]\n    data$assay_feature <- x[observed,j]\n    if(stats::sd(data$assay_feature)<1e-10) {\n      result$status <- \"constant_feature\"\n      output[[j]] <- result\n      next\n    }\n    design <- try(stats::model.matrix(stats::delete.response(stats::terms(form)),data=data),silent=TRUE)\n    if (inherits(design,\"try-error\") || qr(design)$rank < ncol(design)) {\n      result$status <- \"aliased_design\"\n      output[[j]] <- result\n      next\n    }\n    fit <- try(survival::coxph(\n      form,data=data,ties=ties,x=TRUE,\n      control=survival::coxph.control(iter.max=60,timefix=FALSE)\n    ),silent=TRUE)\n    if (inherits(fit,\"try-error\") || any(!is.finite(stats::coef(fit))) ||\n        any(abs(stats::coef(fit))>12)) {\n      result$status <- \"cox_nonconvergence_or_separation\"\n      output[[j]] <- result\n      next\n    }\n    beta <- as.numeric(stats::coef(fit)[\"assay_feature\"])\n    v <- try(stats::vcov(fit)[\"assay_feature\",\"assay_feature\"],silent=TRUE)\n    if(inherits(v,\"try-error\") || !is.finite(v) || v<=0) {\n      result$status <- \"invalid_cox_variance\"\n      output[[j]] <- result\n      next\n    }\n    se <- sqrt(v)\n    zph <- try(survival::cox.zph(fit,transform=\"km\"),silent=TRUE)\n    if(inherits(zph,\"try-error\") || !\"assay_feature\"%in%rownames(zph$table)) {\n      result$status <- \"ph_diagnostic_unavailable\"\n      output[[j]] <- result\n      next\n    }\n    feature_ph <- as.numeric(zph$table[\"assay_feature\",\"p\"])\n    global_ph <- if(\"GLOBAL\"%in%rownames(zph$table))\n      as.numeric(zph$table[\"GLOBAL\",\"p\"]) else NA_real_\n    if(!is.finite(feature_ph) || !is.finite(global_ph)) {\n      result$status <- \"ph_diagnostic_unavailable\"\n      output[[j]] <- result\n      next\n    }\n    result$effect <- beta\n    result$standardError <- se\n    result$pValue <- 2*stats::pnorm(-abs(beta/se))\n    result$hazardRatio <- exp(beta)\n    result$ciLow <- beta-1.959963984540054*se\n    result$ciHigh <- beta+1.959963984540054*se\n    result$proportionalHazardsP <- feature_ph\n    result$globalPhP <- global_ph\n    result$status <- if(feature_ph<0.05 || global_ph<0.05) \"ph_assumption_warning\" else \"ph_test_not_rejected\"\n    output[[j]] <- result\n  }\n  results <- do.call(rbind,output)\n  # The full supplied family remains in the BH denominator: unsuccessful\n  # fits receive p=1, not a post-hoc reduction in the number of tests.\n  family_p <- ifelse(is.finite(results$pValue),results$pValue,1)\n  q <- stats::p.adjust(family_p,method=\"BH\")\n  results$qValue[is.finite(results$pValue)] <- q[is.finite(results$pValue)]\n  results <- results[order(is.na(results$qValue),results$qValue),,drop=FALSE]\n  rownames(results) <- NULL\n  dir.create(output_dir,recursive=TRUE,showWarnings=FALSE)\n  utils::write.csv(results,file.path(output_dir,\"cox_results.csv\"),row.names=FALSE)\n  counts <- as.list(table(results$status))\n  list(\n    results=results,\n    summary=list(\n      method=paste0(\"survival::coxph, ties=\",ties),\n      attemptedFeatures=ncol(x),estimable=sum(is.finite(results$pValue)),\n      nSubjects=nrow(x),events=sum(events),tieMethod=ties,\n      nuisanceTerms=nuisance,statusCounts=counts,\n      importantLimit=\"A non-significant cox.zph test never proves PH; informative censoring, competing risks, time-dependent exposure and selective feature missingness remain untested.\"\n    )\n  )\n}\n","paired_rnaseq_reference.R":"# Subject-blocked RNA-seq reference differential expression.\n# \"paired\" = two unique biological samples per subject (same individual or\n# same independently derived cell line), ONE in each condition. It does NOT\n# describe technical replicates or two independent patients.\n#\n# Guard before DESeq2/limma-voom, after exact assay-input checks and aggregation.\n# Never silently downgrade an invalid paired study to an independent design.\npaired_rnaseq_design <- function(counts,metadata,protocol,covariates=character()) {\n  if(!is.matrix(counts)||!is.numeric(counts)||ncol(counts)<20L||\n     is.null(rownames(counts))||is.null(colnames(counts))||\n     anyNA(rownames(counts))||anyNA(colnames(counts))||\n     any(!nzchar(rownames(counts)))||any(!nzchar(colnames(counts)))||\n     anyDuplicated(rownames(counts))||anyDuplicated(colnames(counts))||\n     any(!is.finite(counts))||any(counts<0)||\n     any(abs(counts-round(counts))>1e-8)||any(rowSums(counts)<=0))\n    stop(\"Paired RNA-seq requires genuine finite nonnegative integer counts, unique measured samples and >=20 features.\",call.=FALSE)\n  if(!is.data.frame(metadata)||\n     !all(c(\"subject_id\",\"sample_id\",\"condition\",\"batch\")%in%names(metadata))||\n     is.null(rownames(metadata))||anyDuplicated(rownames(metadata))||\n     nrow(metadata)!=nrow(counts)||!setequal(rownames(metadata),rownames(counts)))\n    stop(\"Paired RNA-seq sample/metadata identifiers do not match exactly.\",call.=FALSE)\n  m<-metadata[match(rownames(counts),rownames(metadata)),,drop=FALSE]\n  for(field in c(\"subject_id\",\"sample_id\",\"condition\")) {\n    a<-as.character(m[[field]])\n    if(anyNA(a)||any(!nzchar(trimws(a))))\n      stop(paste(\"Paired RNA-seq missing required\",field,\"identifier.\"),call.=FALSE)\n  }\n  if(anyDuplicated(as.character(m$sample_id))||\n     !identical(as.character(m$sample_id),rownames(counts)))\n    stop(\"Paired RNA-seq requires one unique biological sample identifier per measured assay after technical aggregation.\",call.=FALSE)\n  groups<-sort(unique(as.character(m$condition)))\n  if(length(groups)!=2L)\n    stop(\"Paired RNA-seq requires exactly two measured conditions.\",call.=FALSE)\n  subjects<-sort(unique(as.character(m$subject_id)))\n  if(length(subjects)<4L)\n    stop(\"Paired RNA-seq requires >=4 independent subjects or biological cell lines with both conditions; this is not a statistical power guarantee.\",call.=FALSE)\n  observed<-table(factor(as.character(m$subject_id),levels=subjects),\n                  factor(as.character(m$condition),levels=groups))\n  if(!identical(dim(observed),c(length(subjects),2L))||\n     any(observed!=1L)||nrow(m)!=2L*length(subjects))\n    stop(\"Paired RNA-seq requires exactly one measured biological sample per subject and condition; missing or duplicated pairs are not silently removed.\",call.=FALSE)\n\n  m$subject_id<-factor(as.character(m$subject_id),levels=subjects)\n  m$condition<-factor(as.character(m$condition),levels=groups)\n  # Paired identity is the first blocking effect, primary condition LAST. This\n  # makes a limma-voom last coefficient the planned treatment contrast.\n  nuisance<-setdiff(varying_terms(m,covariates),c(\"subject_id\",\"condition\"))\n  if(length(nuisance)){\n    for(k in nuisance){\n      v<-as.character(m[[k]])\n      if(anyNA(v)||any(!nzchar(trimws(v))))\n        stop(paste(\"Paired RNA-seq cannot fit a missing or incomplete nuisance covariate:\",k),call.=FALSE)\n    }\n  }\n  formula<-safe_formula(c(\"subject_id\",nuisance,\"condition\"))\n  design<-stats::model.matrix(formula,data=m)\n  if(nrow(design)!=nrow(counts)||qr(design)$rank!=ncol(design)||\n     nrow(design)-ncol(design)<2L)\n    stop(\"Paired RNA-seq design is confounded or has fewer than two residual degrees of freedom; no reference fit attempted.\",call.=FALSE)\n  # An exploratory result reports its sign explicitly (alphabetical group\n  # reference). A confirmatory fit requires the researcher to declare BOTH\n  # levels and their order; no implicit contrast is acceptable.\n  declared<-identical(protocol$analysisIntent,\"confirmatory\")\n  contrast<-if(declared){\n    rnaseq_confirmatory_explicit_contrast(protocol,groups)\n  } else c(\"condition\",groups[[2L]],groups[[1L]])\n  contract<-list(\n    status=\"eligible_for_reference_fitting_only\",\n    pairing=\"same_subject_two_conditions\",\n    design=deparse(formula,width.cutoff=500L),\n    model_samples=nrow(m),\n    independent_biological_subjects=length(subjects),\n    biological_pairs=length(subjects),\n    measured_samples_per_condition=as.list(table(m$condition)),\n    residual_degrees_of_freedom=nrow(design)-ncol(design),\n    explicit_primary_contrast=as.list(unname(contrast)),\n    contrast_was_prespecified=declared,\n    batch_and_covariate_terms=as.list(nuisance),\n    sample_identifiers_exact=TRUE,\n    all_subject_condition_cells_observed_once=TRUE,\n    certified=FALSE,\n    limitations=c(\n      \"Two assays from one subject are not independent subjects.\",\n      \"Four pairs is a software eligibility guard, not a power guarantee.\",\n      \"Only an additive within-subject effect is tested; unmodeled condition-by-subject interactions remain a limitation.\",\n      \"Independent biological and FDR validation are still required.\"\n    )\n  )\n  list(metadata=m,design_formula=formula,contrast=unname(contrast),contract=contract)\n}\n","reference_full_results.R":"# Complete R reference-method result tables, for use from the consented LOCAL R\n# backend only. No external web services or global caches are involved.\n# Scientific contract: show a top-100 preview, but do NOT disguise it as\n# an exhaustive result. Every fitted feature and every fitted result column\n# must be preserved, including non-significant genes and missing q values.\n# Optional, operator-controlled retention for an oversized, sensitive result.\n# No HTTP download endpoint is exposed. The researcher must explicitly set\n# PMX_MULTIOMICS_RESULTS_DIR on their own machine and retrieve the CSV locally.\n# Random subdirectories have mode 0700; filenames never contain user-supplied IDs.\narchive_large_reference_table <- function(csv_path, archive_dir, max_local_bytes=1024^3) {\n  if(!is.character(archive_dir)||length(archive_dir)!=1L||\n     is.na(archive_dir)||!nzchar(trimws(archive_dir)))\n    return(list(saved=FALSE,reason=\"not_configured\"))\n  if(!dir.exists(archive_dir)||file.access(archive_dir,2L)!=0L)\n    return(list(saved=FALSE,reason=\"directory_missing_or_unwritable\"))\n  bytes <- unname(file.info(csv_path)$size)\n  if(!is.finite(bytes)||bytes>max_local_bytes)\n    return(list(saved=FALSE,reason=\"local_archive_size_limit\"))\n  if(!requireNamespace(\"digest\",quietly=TRUE))\n    return(list(saved=FALSE,reason=\"sha256_digest_package_unavailable\"))\n  private <- tempfile(\"pmx_reference_\",tmpdir=normalizePath(archive_dir,mustWork=TRUE))\n  if(!dir.create(private,mode=\"0700\",showWarnings=FALSE))\n    return(list(saved=FALSE,reason=\"could_not_create_private_directory\"))\n  saved <- file.path(private,\"fitted_reference.csv\")\n  if(!file.copy(csv_path,saved,overwrite=FALSE,copy.mode=FALSE)){\n    unlink(private,recursive=TRUE,force=TRUE)\n    return(list(saved=FALSE,reason=\"file_copy_failed\"))\n  }\n  Sys.chmod(private,mode=\"0700\")\n  Sys.chmod(saved,mode=\"0600\")\n  sha <- digest::digest(file=saved,algo=\"sha256\",serialize=FALSE)\n  list(saved=TRUE,id=basename(private),bytes=bytes,sha256=sha)\n}\n\nreference_complete_table <- function(x, original_features=NA_integer_,\n                                     max_wire_bytes=64L*1024L*1024L,\n                                     local_archive_dir=Sys.getenv(\"PMX_MULTIOMICS_RESULTS_DIR\",\"\"),\n                                     max_local_bytes=1024^3) {\n  if(is.null(x))stop(\"Complete reference export requires fitted results.\")\n  tab <- as.data.frame(x, check.names=FALSE, stringsAsFactors=FALSE)\n  if(!\"feature\" %in% names(tab))stop(\"Reference result lacks feature IDs.\")\n  ids <- as.character(tab$feature)\n  if(anyNA(ids)||any(!nzchar(ids))||anyDuplicated(ids))\n    stop(\"Complete reference result contains missing or duplicated feature IDs.\")\n  if(nrow(tab)!=length(ids))stop(\"Inconsistent reference feature count.\")\n  if(!is.numeric(max_wire_bytes) || length(max_wire_bytes)!=1L ||\n     !is.finite(max_wire_bytes) || max_wire_bytes < 256L)\n    stop(\"Invalid maximum wire export size.\")\n  value_types <- vapply(tab,function(y) {\n    if(is.integer(y))\"integer\" else if(is.numeric(y))\"numeric\"\n    else if(is.logical(y))\"logical\" else \"string\"\n  },character(1))\n  all_rows <- nrow(tab)\n  # This estimate is only a preflight; the final exact byte count is\n  # verified below. This guard prevents accidentally serializing a multi-GB\n  # study into one HTTP JSON response.\n  if(as.double(object.size(tab))>max_wire_bytes*3 && !nzchar(local_archive_dir)){\n    return(list(referenceTableStatus=\"too_large\",referenceTableComplete=FALSE,\n      referenceTableRows=all_rows,referenceTableExportedRows=0L,\n      referenceTableColumns=as.list(names(tab)),\n      referenceTableTypes=as.list(value_types),\n      referenceTableCsv=NULL,referenceTableMessage=\n      \"R reference result exceeds the HTTP budget and was NOT retained by this API. To preserve it, explicitly configure PMX_MULTIOMICS_RESULTS_DIR on the local R server and rerun. Top rows are only a preview.\"))\n  }\n  # Stream to a temporary LOCAL CSV first, so a large payload can be rejected\n  # before an extra full-size string is allocated in the HTTP JSON response.\n  export_path <- tempfile(\"pmx_reference_full_\",fileext=\".csv\")\n  on.exit(unlink(export_path),add=TRUE)\n  utils::write.csv(tab,file=export_path,row.names=FALSE,na=\"NA\",quote=TRUE)\n  bytes <- unname(file.info(export_path)$size)\n  if(!is.finite(bytes))stop(\"Unable to determine full R CSV size.\")\n  if(bytes>max_wire_bytes){\n    local <- archive_large_reference_table(export_path,local_archive_dir,max_local_bytes)\n    locally_saved <- isTRUE(local$saved)\n    return(list(\n      referenceTableStatus=if(locally_saved)\"too_large_archived_locally\" else \"too_large\",\n      referenceTableComplete=FALSE,\n      referenceTableRows=all_rows,referenceTableExportedRows=0L,\n      referenceTableColumns=as.list(names(tab)),\n      referenceTableTypes=as.list(value_types),\n      referenceTableCsv=NULL,referenceTableBytes=bytes,\n      referenceTableLocalArchiveId=if(locally_saved)local$id else NULL,\n      referenceTableLocalArchiveSha256=if(locally_saved)local$sha256 else NULL,\n      referenceTableLocalArchiveBytes=if(locally_saved)local$bytes else NULL,\n      referenceTableMessage=if(locally_saved)\n        paste(\"Too large for JSON: full CSV saved ONLY in the explicitly configured local\",\n              \"PMX_MULTIOMICS_RESULTS_DIR directory under a private subfolder;\",\n              \"not included in browser ZIP. Verify its SHA-256 and retrieve locally.\")\n      else paste(\"Too large for JSON, NOT retained by this API (reason:\",\n                 local$reason,\"). Configure PMX_MULTIOMICS_RESULTS_DIR in a\",\n                 \"private local R environment and rerun to preserve the full CSV.\")\n    ))\n  }\n  csv <- readChar(export_path,nchars=as.integer(bytes),useBytes=TRUE)\n  if(!identical(nchar(csv,type=\"bytes\"),as.integer(bytes)))\n    stop(\"Full R CSV readback mismatch.\")\n  if(!is.na(original_features)){\n    original_features<-as.integer(original_features)\n    if(original_features<all_rows)\n      stop(\"Fitted reference result unexpectedly has more feature rows than input.\")\n  }\n  list(referenceTableStatus=\"complete\",referenceTableComplete=TRUE,\n    referenceTableRows=all_rows,referenceTableExportedRows=all_rows,\n    referenceTableOriginalFeatures=if(is.na(original_features))NULL else original_features,\n    referenceTableExcludedBeforeFit=if(is.na(original_features))NULL else\n      original_features-all_rows,\n    referenceTableColumns=as.list(names(tab)),referenceTableTypes=as.list(value_types),\n    referenceTableCsv=csv,referenceTableBytes=bytes,\n    referenceTableCsvFormat=\"RFC4180-quoted UTF-8, NA token 'NA', unmodified original feature IDs\",\n    referenceTableMessage=\"This is the complete fitted reference table, not a biological or statistical certification. Raw IDs are unchanged; do not open untrusted CSV in spreadsheet software without formula-safety controls.\"\n  )\n}\n","external_validation.R":"# Independent validation of frozen model predictions.\n#\n# This module deliberately evaluates predictions that were generated without\n# refitting on the validation cohort. It does not perform feature selection,\n# tune hyperparameters or retrain a multi-omics model on validation data.\n# That separation is the core safeguard against calling internal resampling\n# \"external validation\".\n\nvalidation_clip_probability <- function(x, eps = 1e-6) {\n  pmin(1 - eps, pmax(eps, as.numeric(x)))\n}\n\nvalidation_average_ranks <- function(x) {\n  x <- as.numeric(x)\n  out <- rep(NA_real_, length(x))\n  ok <- is.finite(x)\n  out[ok] <- rank(x[ok], ties.method = \"average\")\n  out\n}\n\nvalidation_binary_auc <- function(observed, score) {\n  y <- as.integer(observed)\n  s <- as.numeric(score)\n  ok <- is.finite(y) & is.finite(s) & y %in% c(0L, 1L)\n  y <- y[ok]\n  s <- s[ok]\n  n1 <- sum(y == 1L)\n  n0 <- sum(y == 0L)\n  if (!n1 || !n0) return(NA_real_)\n  ranks <- rank(s, ties.method = \"average\")\n  (sum(ranks[y == 1L]) - n1 * (n1 + 1) / 2) / (n1 * n0)\n}\n\nvalidation_binary_metrics <- function(observed, prediction, prediction_kind = c(\"probability\", \"score\")) {\n  prediction_kind <- match.arg(prediction_kind)\n  y <- as.integer(observed)\n  p <- as.numeric(prediction)\n  ok <- is.finite(y) & is.finite(p) & y %in% c(0L, 1L)\n  y <- y[ok]\n  p <- p[ok]\n  if (length(y) < 4L || length(unique(y)) < 2L) {\n    return(list(status = \"not_estimable\", n = length(y), reason = \"Both binary classes and at least four evaluable observations are required.\"))\n  }\n  auc <- validation_binary_auc(y, p)\n  result <- list(\n    status = \"ok\",\n    n = length(y),\n    events = sum(y == 1L),\n    non_events = sum(y == 0L),\n    auc = auc,\n    prediction_kind = prediction_kind\n  )\n  if (identical(prediction_kind, \"probability\")) {\n    prob <- validation_clip_probability(p)\n    result$brier <- mean((prob - y)^2)\n    result$log_loss <- -mean(y * log(prob) + (1 - y) * log(1 - prob))\n    lp <- qlogis(prob)\n    calibration <- try(stats::glm(y ~ lp, family = stats::binomial()), silent = TRUE)\n    if (!inherits(calibration, \"try-error\")) {\n      coefs <- stats::coef(calibration)\n      result$calibration_intercept <- unname(coefs[[1]])\n      result$calibration_slope <- unname(coefs[[2]])\n    } else {\n      result$calibration_intercept <- NA_real_\n      result$calibration_slope <- NA_real_\n    }\n  }\n  result\n}\n\nvalidation_continuous_metrics <- function(observed, prediction) {\n  y <- as.numeric(observed)\n  p <- as.numeric(prediction)\n  ok <- is.finite(y) & is.finite(p)\n  y <- y[ok]\n  p <- p[ok]\n  if (length(y) < 3L) return(list(status = \"not_estimable\", n = length(y), reason = \"At least three evaluable observations are required.\"))\n  residual <- p - y\n  sst <- sum((y - mean(y))^2)\n  r2 <- if (sst > 0) 1 - sum(residual^2) / sst else NA_real_\n  calibration <- try(stats::lm(y ~ p), silent = TRUE)\n  list(\n    status = \"ok\",\n    n = length(y),\n    rmse = sqrt(mean(residual^2)),\n    mae = mean(abs(residual)),\n    r2 = r2,\n    calibration_intercept = if (!inherits(calibration, \"try-error\")) unname(stats::coef(calibration)[[1]]) else NA_real_,\n    calibration_slope = if (!inherits(calibration, \"try-error\")) unname(stats::coef(calibration)[[2]]) else NA_real_\n  )\n}\n\nvalidation_poisson_deviance <- function(observed, prediction) {\n  y <- as.numeric(observed)\n  mu <- pmax(as.numeric(prediction), 1e-12)\n  ok <- is.finite(y) & is.finite(mu) & y >= 0 & mu > 0\n  y <- y[ok]\n  mu <- mu[ok]\n  if (!length(y)) return(NA_real_)\n  terms <- ifelse(y == 0, mu, y * log(y / mu) - (y - mu))\n  2 * mean(terms)\n}\n\nvalidation_count_metrics <- function(observed, prediction) {\n  base <- validation_continuous_metrics(observed, prediction)\n  if (!identical(base$status, \"ok\")) return(base)\n  base$mean_poisson_deviance <- validation_poisson_deviance(observed, prediction)\n  base\n}\n\nvalidation_harrell_cindex <- function(time, event, risk) {\n  time <- as.numeric(time)\n  event <- as.integer(event)\n  risk <- as.numeric(risk)\n  ok <- is.finite(time) & is.finite(event) & is.finite(risk) & time >= 0 & event %in% c(0L, 1L)\n  time <- time[ok]\n  event <- event[ok]\n  risk <- risk[ok]\n  comparable <- 0\n  concordant <- 0\n  tied <- 0\n  n <- length(time)\n  if (n < 2L) return(list(c_index = NA_real_, comparable_pairs = 0L))\n  for (i in seq_len(n - 1L)) {\n    for (j in (i + 1L):n) {\n      earlier <- NA_integer_\n      later <- NA_integer_\n      if (time[[i]] < time[[j]] && event[[i]] == 1L) {\n        earlier <- i; later <- j\n      } else if (time[[j]] < time[[i]] && event[[j]] == 1L) {\n        earlier <- j; later <- i\n      } else {\n        next\n      }\n      comparable <- comparable + 1L\n      if (risk[[earlier]] > risk[[later]]) concordant <- concordant + 1L\n      else if (risk[[earlier]] == risk[[later]]) tied <- tied + 1L\n    }\n  }\n  list(\n    c_index = if (comparable) (concordant + 0.5 * tied) / comparable else NA_real_,\n    comparable_pairs = comparable,\n    concordant_pairs = concordant,\n    tied_risk_pairs = tied\n  )\n}\n\nvalidation_survival_metrics <- function(time, event, risk) {\n  time <- as.numeric(time)\n  event <- as.integer(event)\n  risk <- as.numeric(risk)\n  ok <- is.finite(time) & is.finite(event) & is.finite(risk) & time >= 0 & event %in% c(0L, 1L)\n  time <- time[ok]\n  event <- event[ok]\n  risk <- risk[ok]\n  if (length(time) < 5L || sum(event == 1L) < 2L) {\n    return(list(status = \"not_estimable\", n = length(time), events = sum(event == 1L), reason = \"At least five subjects and two observed events are required.\"))\n  }\n  ci <- validation_harrell_cindex(time, event, risk)\n  list(\n    status = \"ok\",\n    n = length(time),\n    events = sum(event == 1L),\n    censored = sum(event == 0L),\n    c_index = ci$c_index,\n    comparable_pairs = ci$comparable_pairs,\n    tied_risk_pairs = ci$tied_risk_pairs\n  )\n}\n\nvalidation_multiclass_metrics <- function(observed, probabilities, sum_tolerance = 1e-6) {\n  y <- as.character(observed)\n  probs <- as.matrix(probabilities)\n  storage.mode(probs) <- \"double\"\n  classes <- colnames(probs)\n  if (length(classes) < 2L || anyNA(classes) || any(!nzchar(classes)) ||\n      anyDuplicated(classes)) {\n    stop(\"Multiclass predictions need at least two distinct, nonempty probability column labels.\", call. = FALSE)\n  }\n  if (length(y) != nrow(probs)) {\n    stop(\"Multiclass observed outcomes and probability rows must have equal lengths.\", call. = FALSE)\n  }\n  # Out-of-range probabilities are invalid *data*, not an inconvenience to\n  # be fixed by clipping or renormalizing before reporting calibration.\n  if (any(is.finite(probs) & (probs < 0 | probs > 1))) {\n    stop(\"Multiclass probabilities must individually lie within [0,1].\", call. = FALSE)\n  }\n  fully_finite <- rowSums(is.finite(probs)) == ncol(probs)\n  if (any(fully_finite)) {\n    sum_by_row <- rowSums(probs[fully_finite, , drop = FALSE])\n    if (any(abs(sum_by_row - 1) > sum_tolerance)) {\n      stop(\"Multiclass probability rows must sum to 1 (absolute tolerance 1e-6); frozen scores must not be renormalized during evaluation.\", call. = FALSE)\n    }\n  }\n  # Missing outcomes, classes absent from the submitted probability panel, or\n  # missing predictions remain INCOMPLETE evidence. They are not silently\n  # relabelled as a complete external validation by the parent function.\n  ok <- !is.na(y) & nzchar(y) & y %in% classes & fully_finite\n  y <- y[ok]\n  probs <- probs[ok, , drop = FALSE]\n  if (length(y) < 5L || length(unique(y)) < 2L) {\n    return(list(status = \"not_estimable\", n = length(y)))\n  }\n  # Tiny floating-point sum errors within tolerance are accepted AS SUPPLIED,\n  # not repaired; even model ranking can change after unsafe normalization.\n  predicted <- classes[max.col(probs, ties.method = \"first\")]\n  truth_index <- match(y, classes)\n  p_true <- validation_clip_probability(probs[cbind(seq_along(y), truth_index)])\n  class_recall <- vapply(unique(y), function(cls) mean(predicted[y == cls] == cls), numeric(1))\n  one_vs_rest_auc <- vapply(classes, function(cls) {\n    validation_binary_auc(as.integer(y == cls), probs[, cls])\n  }, numeric(1))\n  finite_auc <- one_vs_rest_auc[is.finite(one_vs_rest_auc)]\n  list(\n    status = \"ok\",\n    n = length(y),\n    classes = as.list(table(y)),\n    accuracy = mean(predicted == y),\n    balanced_accuracy = mean(class_recall, na.rm = TRUE),\n    log_loss = -mean(log(p_true)),\n    macro_auc_ovr = if (length(finite_auc)) mean(finite_auc) else NA_real_,\n    per_class_auc_ovr = as.list(one_vs_rest_auc)\n  )\n}\n\nvalidation_percentile_ci <- function(values, level = 0.95) {\n  values <- as.numeric(values)\n  values <- values[is.finite(values)]\n  if (length(values) < 20L) return(c(lower = NA_real_, upper = NA_real_))\n  alpha <- (1 - level) / 2\n  out <- unname(stats::quantile(values, probs = c(alpha, 1 - alpha), names = FALSE, type = 7))\n  names(out) <- c(\"lower\", \"upper\")\n  out\n}\n\nvalidation_bootstrap_scalar <- function(data, metric_fn, repetitions = 1000L, seed = 20260928L, level = 0.95) {\n  repetitions <- as.integer(max(0L, repetitions))\n  if (!repetitions || nrow(data) < 5L) {\n    return(list(\n      repetitions = repetitions,\n      valid_repetitions = 0L,\n      estimate_distribution = numeric(),\n      ci = c(lower = NA_real_, upper = NA_real_)\n    ))\n  }\n  set.seed(as.integer(seed))\n  values <- rep(NA_real_, repetitions)\n  for (b in seq_len(repetitions)) {\n    idx <- sample.int(nrow(data), nrow(data), replace = TRUE)\n    candidate <- suppressWarnings(as.numeric(metric_fn(data[idx, , drop = FALSE])))\n    values[[b]] <- if (length(candidate) && is.finite(candidate[[1]])) candidate[[1]] else NA_real_\n  }\n  valid <- sum(is.finite(values))\n  list(\n    repetitions = repetitions,\n    valid_repetitions = valid,\n    invalid_repetitions = repetitions - valid,\n    seed = as.integer(seed),\n    ci_level = level,\n    ci = validation_percentile_ci(values, level),\n    estimate_distribution = values\n  )\n}\n\nvalidate_external_predictions <- function(\n  data,\n  outcome_type,\n  prediction_column = \"prediction\",\n  outcome_column = \"outcome\",\n  prediction_kind = \"probability\",\n  time_column = \"survival_time\",\n  event_column = \"survival_event\",\n  probability_columns = NULL,\n  independent_cohort = FALSE,\n  cohort_label = NULL,\n  bootstrap_repetitions = 1000L,\n  seed = 20260928L\n) {\n  data <- as.data.frame(data, stringsAsFactors = FALSE)\n  if(!nrow(data))stop(\"External predictions table is empty.\",call.=FALSE)\n  # Identical people must not be silently counted as independent evidence.\n  # IDs are optional for old clients, but lack of an identifier is reported.\n  subject_identity <- if(\"subject_id\" %in% names(data)) {\n    id <- trimws(as.character(data[[\"subject_id\"]]))\n    if(anyNA(data[[\"subject_id\"]]) || any(!nzchar(id)))\n      stop(\"subject_id contains missing/empty identifiers; one frozen prediction per subject is required.\",call.=FALSE)\n    if(anyDuplicated(id))\n      stop(\"Duplicated subject_id in frozen external predictions: repeated persons are not independent observations.\",call.=FALSE)\n    list(status=\"unique\",unique_subjects=length(id),identifier_column=\"subject_id\")\n  } else list(status=\"not_verifiable_without_subject_id\",unique_subjects=NULL,\n    identifier_column=NULL)\n  outcome_type <- tolower(trimws(as.character(outcome_type)))\n  allowed <- c(\"binary\", \"continuous\", \"count\", \"survival\", \"multiclass\")\n  if (!outcome_type %in% allowed) stop(\"Unsupported outcome_type.\", call. = FALSE)\n\n  required <- switch(\n    outcome_type,\n    survival = c(time_column, event_column, prediction_column),\n    multiclass = c(outcome_column, probability_columns),\n    c(outcome_column, prediction_column)\n  )\n  missing_columns <- setdiff(required, names(data))\n  if (length(missing_columns)) stop(paste(\"Missing validation column(s):\", paste(missing_columns, collapse = \", \")), call. = FALSE)\n  if (identical(outcome_type,\"multiclass\")) {\n    if (is.null(probability_columns) || length(probability_columns) < 2L ||\n        anyNA(probability_columns) ||\n        any(!nzchar(trimws(as.character(probability_columns)))) ||\n        anyDuplicated(probability_columns)) {\n      stop(\"Multiclass validation requires at least two distinct, named probability columns.\",call.=FALSE)\n    }\n    if (outcome_column %in% probability_columns) {\n      stop(\"Multiclass outcome column cannot also be a probability column.\",call.=FALSE)\n    }\n  }\n  if (identical(outcome_type,\"count\")) {\n    y_count <- suppressWarnings(as.numeric(data[[outcome_column]]))\n    mu_count <- suppressWarnings(as.numeric(data[[prediction_column]]))\n    if (any(is.finite(y_count) & (y_count < 0 | abs(y_count-round(y_count)) > 1e-8))) {\n      stop(\"Observed count outcomes must be nonnegative whole numbers.\",call.=FALSE)\n    }\n    if (any(is.finite(mu_count) & mu_count < 0)) {\n      stop(\"Predicted count means must be nonnegative.\",call.=FALSE)\n    }\n  }\n  # A probability is defined only on [0,1]. Do not convert impossible\n  # submitted scores into apparently well-calibrated probabilities via clip.\n  if(identical(outcome_type,\"binary\") && identical(prediction_kind,\"probability\")){\n    p <- suppressWarnings(as.numeric(data[[prediction_column]]))\n    if(any(is.finite(p) & (p<0 | p>1)))\n      stop(\"Binary probability predictions must be within [0,1].\",call.=FALSE)\n  }\n\n  metrics <- switch(\n    outcome_type,\n    binary = validation_binary_metrics(data[[outcome_column]], data[[prediction_column]], prediction_kind),\n    continuous = validation_continuous_metrics(data[[outcome_column]], data[[prediction_column]]),\n    count = validation_count_metrics(data[[outcome_column]], data[[prediction_column]]),\n    survival = validation_survival_metrics(data[[time_column]], data[[event_column]], data[[prediction_column]]),\n    multiclass = validation_multiclass_metrics(data[[outcome_column]], data[, probability_columns, drop = FALSE])\n  )\n\n  primary_name <- switch(outcome_type, binary = \"auc\", continuous = \"rmse\", count = \"rmse\", survival = \"c_index\", multiclass = \"balanced_accuracy\")\n  bootstrap <- NULL\n  if (identical(metrics$status, \"ok\") && outcome_type != \"multiclass\") {\n    metric_fn <- switch(\n      outcome_type,\n      binary = function(d) validation_binary_metrics(d[[outcome_column]], d[[prediction_column]], prediction_kind)[[primary_name]],\n      continuous = function(d) validation_continuous_metrics(d[[outcome_column]], d[[prediction_column]])[[primary_name]],\n      count = function(d) validation_count_metrics(d[[outcome_column]], d[[prediction_column]])[[primary_name]],\n      survival = function(d) validation_survival_metrics(d[[time_column]], d[[event_column]], d[[prediction_column]])[[primary_name]]\n    )\n    boot <- validation_bootstrap_scalar(data, metric_fn, repetitions = bootstrap_repetitions, seed = seed)\n    bootstrap <- list(\n      metric = primary_name,\n      repetitions = boot$repetitions,\n      valid_repetitions = boot$valid_repetitions %||% 0L,\n      invalid_repetitions = boot$invalid_repetitions %||% 0L,\n      seed = boot$seed %||% as.integer(seed),\n      ci_level = boot$ci_level %||% 0.95,\n      lower = unname(boot$ci[[\"lower\"]]),\n      upper = unname(boot$ci[[\"upper\"]]),\n      note = \"Percentile bootstrap uncertainty on the frozen external predictions; non-estimable resamples are retained as missing and never replaceable by refitting.\"\n    )\n  }\n\n  # Earlier versions evaluated complete-case rows but still labelled\n  # the result 'external_validation' when some patients were omitted.\n  # Retain partial metrics transparently without assigning that complete label.\n  eligible <- as.integer(metrics$n %||% 0L)\n  fully_evaluated <- identical(metrics$status,\"ok\") &&\n    length(eligible)==1L && is.finite(eligible) && eligible==nrow(data)\n  status <- if(!isTRUE(independent_cohort)) \"independent_status_not_asserted\"\n    else if(fully_evaluated) \"external_validation\"\n    else \"external_validation_incomplete\"\n  list(\n    status = status,\n    subject_identity_audit = subject_identity,\n    cohort_coverage = list(submitted_rows=nrow(data),evaluated_rows=eligible,\n      excluded_rows=nrow(data)-eligible,\n      complete=fully_evaluated,\n      note=if(fully_evaluated) \"All submitted rows were evaluated.\"\n        else \"Some rows were not evaluable; the results are partial and must not be presented as a complete external validation.\"),\n\n    evaluation_status = metrics$status,\n    cohort = cohort_label,\n    independent_cohort_asserted = isTRUE(independent_cohort),\n    outcome_type = outcome_type,\n    primary_metric = primary_name,\n    metrics = metrics,\n    bootstrap = bootstrap,\n    seed = as.integer(seed),\n    methodological_boundary = if (isTRUE(independent_cohort) && fully_evaluated) {\n      \"Predictions are evaluated as supplied and are not refit or tuned on this cohort. Independence is asserted by the analyst and must be supported by study provenance.\"\n    } else {\n      \"Predictions are evaluated without refitting, but cohort independence cannot be verified from a CSV alone, and incomplete/invalid predictions cannot support a full external-validation label. Audit IDs, missing rows and model-development provenance.\"\n    }\n  )\n}\n\n`%||%` <- function(x, y) if (is.null(x) || !length(x) || all(is.na(x))) y else x\n"};
